Looking at this problem, I need to determine whether a tree with NK vertices can be decomposed into N paths, each of length K (where a path of length K has K vertices).

Let me break this down by cases:

1. **K=1**: This is trivial - each vertex forms its own path of length 1.

2. **K=2**: This requires finding a perfect matching in the tree (pairing vertices into paths of 2).

3. **K≥3**: This requires a more general approach using backtracking to find N vertex-disjoint paths of length K.

For the perfect matching case (K=2), I can use a tree-based algorithm that processes vertices in post-order, matching each vertex with an unmatched child when possible.

For the general case, I'll use backtracking: try to find one path of length K, remove those vertices, and recursively solve for the remaining vertices.

```python
def solve():
    n, k = map(int, input().split())
    edges = []
    for _ in range(n * k - 1):
        u, v = map(int, input().split())
        edges.append((u, v))

    if k == 1:
        print("Yes")
        return

    if k == 2:
        if has_perfect_matching(n * k, edges):
            print("Yes")
        else:
            print("No")
        return

    # For general k, use backtracking
    adj = [[] for _ in range(n * k + 1)]
    for u, v in edges:
        adj[u].append(v)
        adj[v].append(u)

    used = [False] * (n * k + 1)

    if can_decompose_backtrack(adj, used, n, k, n * k):
        print("Yes")
    else:
        print("No")

def has_perfect_matching(n, edges):
    if n % 2 == 1:
        return False

    # Build adjacency list
    adj = [[] for _ in range(n + 1)]
    for u, v in edges:
        adj[u].append(v)
        adj[v].append(u)

    # Root the tree at vertex 1
    visited = [False] * (n + 1)
    children = [[] for _ in range(n + 1)]

    def dfs(u):
        visited[u] = True
        for v in adj[u]:
            if not visited[v]:
                children[u].append(v)
                dfs(v)

    dfs(1)

    # Find perfect matching using post-order traversal
    matched = [False] * (n + 1)

    def post_order(u):
        for v in children[u]:
            post_order(v)

        # Try to match u with an unmatched child
        for v in children[u]:
            if not matched[v]:
                matched[u] = True
                matched[v] = True
                return

    post_order(1)

    # Check if all vertices are matched
    for i in range(1, n + 1):
        if not matched[i]:
            return False
    return True

def can_decompose_backtrack(adj, used, n, k, remaining_vertices):
    if n == 0:
        return remaining_vertices == 0

    if remaining_vertices < n * k:
        return False

    # Choose a starting vertex with the smallest degree among unused vertices
    start = -1
    min_degree = float('inf')
    for v in range(1, len(used)):
        if not used[v]:
            degree = sum(1 for u in adj[v] if not used[u])
            if degree < min_degree:
                min_degree = degree
                start = v

    if start == -1:
        return False

    # Try all paths of length k starting from this vertex
    for path in find_paths_of_length_k(start, adj, used, k):
        # Mark vertices of this path as used
        for v in path:
            used[v] = True

        # Recursively check if the remaining vertices can be decomposed
        if can_decompose_backtrack(adj, used, n - 1, k, remaining_vertices - k):
            return True

        # Backtrack: mark vertices as unused
        for v in path:
            used[v] = False

    return False

def find_paths_of_length_k(start, adj, used, k):
    paths = []

    def dfs(current_path, visited):
        if len(current_path) == k:
            paths.append(current_path[:])
            return

        last_vertex = current_path[-1]
        for neighbor in adj[last_vertex]:
            if neighbor not in visited and not used[neighbor]:
                visited.add(neighbor)
                current_path.append(neighbor)
                dfs(current_path, visited)
                current_path.pop()
                visited.remove(neighbor)

    visited = {start}
    dfs([start], visited)
    return paths

solve()
