class Solution:
    def maximumLength(self, nums: List[int]) -> int:
        # Scenario 1.1: All elements have even parity
        even_count = sum(1 for num in nums if num % 2 == 0)

        # Scenario 1.2: All elements have odd parity
        odd_count = sum(1 for num in nums if num % 2 == 1)

        # Scenario 2.1: Alternating pattern starting with even
        even_odd_count = 0
        for num in nums:
            if (even_odd_count % 2 == 0 and num % 2 == 0) or (even_odd_count % 2 == 1 and num % 2 == 1):
                even_odd_count += 1

        # Scenario 2.2: Alternating pattern starting with odd
        odd_even_count = 0
        for num in nums:
            if (odd_even_count % 2 == 0 and num % 2 == 1) or (odd_even_count % 2 == 1 and num % 2 == 0):
                odd_even_count += 1

        return max(even_count, odd_count, even_odd_count, odd_even_count)
