class Solution:
    def maxDistinctElements(self, nums: List[int], k: int) -> int:
        nums.sort()
        taken = set()

        for num in nums:
            # Find the smallest valid value not taken
            for val in range(max(1, num - k), num + k + 1):
                if val not in taken:
                    taken.add(val)
                    break

        return len(taken)
