import sys

class SegmentTree:
    def __init__(self, size, initial_val):
        self.n = 1
        self.size = size
        self.initial_val = initial_val
        while self.n < self.size:
            self.n <<= 1
        self.min_tree = [initial_val] * (2 * self.n)
        self.lazy = [float('inf')] * (2 * self.n)

    def _push(self, node, l, r):
        if self.lazy[node] == float('inf'):
            return
        self.min_tree[node] = min(self.min_tree[node], self.lazy[node])
        if l < r:
            self.lazy[node*2] = min(self.lazy[node*2], self.lazy[node])
            self.lazy[node*2+1] = min(self.lazy[node*2+1], self.lazy[node])
        self.lazy[node] = float('inf')

    def range_update(self, a, b, val):
        self._update(a, b, val, 1, 1, self.n)

    def _update(self, a, b, val, node, l, r):
        self._push(node, l, r)
        if a > r or b < l:
            return
        if a <= l and r <= b:
            self.lazy[node] = min(self.lazy[node], val)
            self._push(node, l, r)
            return
        mid = (l + r) // 2
        self._update(a, b, val, node*2, l, mid)
        self._update(a, b, val, node*2+1, mid+1, r)
        self.min_tree[node] = min(self.min_tree[node*2], self.min_tree[node*2+1])

    def range_query(self, a, b):
        return self._query(a, b, 1, 1, self.n)

    def _query(self, a, b, node, l, r):
        self._push(node, l, r)
        if a > r or b < l:
            return self.initial_val
        if a <= l and r <= b:
            return self.min_tree[node]
        mid = (l + r) // 2
        left = self._query(a, b, node*2, l, mid)
        right = self._query(a, b, node*2+1, mid+1, r)
        return min(left, right)

def main():
