    bars = []
    for idx in range(N):
        R, C, L = map(int, sys.stdin.readline().split())
        bars.append((R, C, L, idx))

    bars.sort(key=lambda x: (-x[0]))
    initial_val = H + 1
    seg = SegmentTree(W, initial_val)
    ans = [0] * N

    for bar in bars:
        R_initial, C, L, original_idx = bar
        start = C
        end = C + L - 1
        min_obs = seg.range_query(start, end)
        r_i = min_obs - 1 if min_obs <= H else H
        seg.range_update(start, end, r_i)
        ans[original_idx] = r_i

    for a in ans:
        print(a)

if __name__ == '__main__':
