class Solution:
    def minOperations(self, n: int, m: int) -> int:
        import heapq

        def sieve_of_eratosthenes(n):
            primes = [True for i in range(n+1)]
            p = 2
            while (p * p <= n):
                if (primes[p] == True):
                    for i in range(p * p, n+1, p):
                        primes[i] = False
                p += 1
            return [p for p in range(2, n+1) if primes[p]]

        if len(str(n)) != len(str(m)):
            return -1

        # Pre-compute primes up to 10^4
        primes = set(sieve_of_eratosthenes(10000))

        if n in primes or m in primes:
            return -1

        # Dijkstra's algorithm
        priority_queue = [(n, n)]  # (cost_so_far, current_number)
        heapq.heapify(priority_queue)
        cost_map = {n: n}  # Maps state to its minimum cost

        while priority_queue:
            cost, current = heapq.heappop(priority_queue)

            if current == m:
                return cost

            if cost > cost_map.get(current, float('inf')):
                continue

            # Generate all possible next states
            current_digits = [int(digit) for digit in str(current)]

            for i in range(len(current_digits)):
                # Increase the digit
                if current_digits[i] < 9:
                    new_digits = current_digits.copy()
                    new_digits[i] += 1

                    new_number = int(''.join(map(str, new_digits)))

                    if new_number not in primes:
                        new_cost = cost + new_number
                        if new_cost < cost_map.get(new_number, float('inf')):
                            cost_map[new_number] = new_cost
                            heapq.heappush(priority_queue, (new_cost, new_number))

                # Decrease the digit
                if current_digits[i] > 0:
                    new_digits = current_digits.copy()
                    new_digits[i] -= 1

                    new_number = int(''.join(map(str, new_digits)))

