        dp = [{} for _ in range(k + 1)]

        for num in nums:
            # Extend existing subsequences with a different element (one additional change)
            for j in range(k - 1, -1, -1):
                max_len = 0
                for val, length in dp[j].items():
                    if val != num:
                        max_len = max(max_len, length)
                if max_len > 0:
                    dp[j+1][num] = max(dp[j+1].get(num, 0), max_len + 1)

            # Extend existing subsequences with the same element (no additional change)
            for j in range(k + 1):
                if num in dp[j]:
                    dp[j][num] = dp[j][num] + 1

            # Start a new subsequence with this element (0 changes)
            dp[0][num] = max(dp[0].get(num, 0), 1)

        result = 0
        for j in range(k + 1):
            for val, length in dp[j].items():
                result = max(result, length)

