I'll use dynamic programming with memoization. The key insight is that I need to track:
- How many 0s and 1s are left to place
- What the last digit placed was
- How many consecutive times that digit has appeared

This ensures I don't exceed the limit of consecutive same digits.

```python
class Solution:
    def numberOfStableArrays(self, zero: int, one: int, limit: int) -> int:
        MOD = 10**9 + 7
        memo = {}

        def dp(zeros_left, ones_left, last, count):
            if zeros_left == 0 and ones_left == 0:
                return 1

            state = (zeros_left, ones_left, last, count)
            if state in memo:
                return memo[state]

            result = 0

            # Place a 0
            if zeros_left > 0:
                if last == 0 and count < limit:
                    result = (result + dp(zeros_left - 1, ones_left, 0, count + 1)) % MOD
                elif last == 1:
                    result = (result + dp(zeros_left - 1, ones_left, 0, 1)) % MOD

            # Place a 1
            if ones_left > 0:
                if last == 1 and count < limit:
                    result = (result + dp(zeros_left, ones_left - 1, 1, count + 1)) % MOD
                elif last == 0:
                    result = (result + dp(zeros_left, ones_left - 1, 1, 1)) % MOD

            memo[state] = result
            return result

        # Start with 0 or 1
        total = 0
        if zero > 0:
            total = (total + dp(zero - 1, one, 0, 1)) % MOD
        if one > 0:
            total = (total + dp(zero, one - 1, 1, 1)) % MOD

        return total
