class Solution:
    def maxProduct(self, nums: List[int], k: int, limit: int) -> int:
        n = len(nums)
        memo = {}

        def dfs(idx, alt_sum, product, selected_count):
            """
            idx: current index in the array
            alt_sum: current alternating sum
            product: current product
            selected_count: number of elements selected so far (used to determine the position in the subsequence)
            """
            if idx == n:
                if selected_count > 0 and alt_sum == k and product <= limit:
                    return product
                return -1

            if (idx, alt_sum, product, selected_count) in memo:
                return memo[(idx, alt_sum, product, selected_count)]

            # Option 1: Skip the current element
            skip_result = dfs(idx + 1, alt_sum, product, selected_count)

            # Option 2: Include the current element
            if selected_count % 2 == 0:  # Even position in the subsequence (0, 2, 4, ...)
                new_alt_sum = alt_sum + nums[idx]
            else:  # Odd position in the subsequence (1, 3, 5, ...)
                new_alt_sum = alt_sum - nums[idx]

            new_product = product * nums[idx]

            if new_product <= limit:
                include_result = dfs(idx + 1, new_alt_sum, new_product, selected_count + 1)
            else:
                include_result = -1

            result = max(skip_result, include_result)
            memo[(idx, alt_sum, product, selected_count)] = result

            return result

