def count_vertices_at_distance(N, X, K):
    # Case K = 0: Only X itself
    if K == 0:
        return 1

    count = 0
    depth_X = X.bit_length() - 1

    # Case 1: Ancestor of X at a distance K
    if K <= depth_X:
        count += 1  # There's exactly one ancestor at distance K

    # Case 2: Descendants of X at a distance K
    start = (1 << K) * X
    if start <= N:
        end = min(start + (1 << K) - 1, N)
        count += end - start + 1

    # Case 3: For each j (1 <= j < K), consider the ancestor of X at distance j
    for j in range(1, min(K, depth_X) + 1):
        ancestor = X >> j
        next_ancestor = X >> (j - 1)

        # Determine the sibling of the path from ancestor to X
        sibling = 2 * ancestor
        if sibling == next_ancestor:
            sibling += 1

        # Check if sibling exists (is <= N)
        if sibling <= N:
            # Count descendants of sibling at distance K-j-1
            remaining_dist = K - j - 1
            if remaining_dist >= 0:
                start = (1 << remaining_dist) * sibling
                if start <= N:
                    end = min(start + (1 << remaining_dist) - 1, N)
                    count += end - start + 1

    return count

