def solve(S, N, K):
    MOD = 998244353

    # dp[i][mask] = the number of good strings up to position i, with the last min(i, K-1) characters in state mask
    dp = [[0] * (1 << (K-1)) for _ in range(N+1)]
    dp[0][0] = 1

    for i in range(N):
        for mask in range(1 << min(i, K-1)):
            if dp[i][mask] == 0:
                continue

            for new_char_bit in [0, 1]:  # 0 for 'A', 1 for 'B'
                new_char = 'B' if new_char_bit else 'A'
                if S[i] != '?' and S[i] != new_char:
                    continue

                # Calculate the new state (mask) after adding the new character
                new_mask = ((mask << 1) & ((1 << (K-1)) - 1)) | new_char_bit

                # Check if the substring of length K ending at position i is a palindrome
                if i >= K-1:
                    is_pal = True
                    if ((mask >> (K-2)) & 1) != new_char_bit:
                        is_pal = False
                    else:
                        for j in range(1, K//2):
                            if ((mask >> (K-2-j)) & 1) != ((mask >> j) & 1):
                                is_pal = False
                                break

                    if is_pal:
                        continue

                dp[i+1][new_mask] = (dp[i+1][new_mask] + dp[i][mask]) % MOD

    # Sum up all possible states at the end
    return sum(dp[N]) % MOD

