Looking at this problem, I need to select cells from a 2D grid with two constraints:
1. No two selected cells can be in the same row
2. All selected values must be unique

This is a dynamic programming problem. I'll group cells by their values and use memoization.

My approach:
1. Group all cells by their values - for each value, track which rows contain it
2. Use DP where state is (current_value_index, bitmask_of_used_rows)
3. For each value, I can either skip it or select it from any available row

```python
class Solution:
    def maxScore(self, grid: List[List[int]]) -> int:
        # Group cells by their values
        value_to_rows = {}
        for row in range(len(grid)):
            for col in range(len(grid[row])):
                value = grid[row][col]
                if value not in value_to_rows:
                    value_to_rows[value] = set()
                value_to_rows[value].add(row)

        values = list(value_to_rows.keys())

        def dp(idx, used_rows):
            if idx == len(values):
                return 0

            if (idx, used_rows) in memo:
                return memo[(idx, used_rows)]

            value = values[idx]

            # Option 1: Don't select this value
            result = dp(idx + 1, used_rows)

            # Option 2: Select this value from one of the available rows
            for row in value_to_rows[value]:
                if not (used_rows & (1 << row)):
                    new_used_rows = used_rows | (1 << row)
                    result = max(result, value + dp(idx + 1, new_used_rows))

            memo[(idx, used_rows)] = result
            return result

        memo = {}
        return dp(0, 0)
