class Solution:
    def countSteppingNumbers(self, low: str, high: str) -> int:
        MOD = 10**9 + 7

        # Count stepping numbers less than or equal to s
        def count_less_than_or_equal(s: str) -> int:
            memo = {}

            def dp(idx, prev_digit, tight, has_started):
                if idx == len(s):
                    return 1 if has_started else 0

                key = (idx, prev_digit, tight, has_started)
                if key in memo:
                    return memo[key]

                result = 0

                # If we haven't started placing digits, we can skip this position (which means the number is shorter)
                if not has_started:
                    result = (result + dp(idx + 1, prev_digit, False, False)) % MOD

                # Determine the range of digits we can place
                upper_bound = int(s[idx]) if tight else 9

                # If we haven't started, we can only place 1-9
                start_range = 1 if not has_started else 0

                for digit in range(start_range, upper_bound + 1):
                    # We can place this digit if we haven't started yet or it's adjacent to the previous digit
                    if not has_started or abs(prev_digit - digit) == 1:
                        # We remain tight if we're tight and we've placed the upper bound
                        new_tight = tight and (digit == upper_bound)
                        result = (result + dp(idx + 1, digit, new_tight, True)) % MOD

                memo[key] = result
                return result

            return dp(0, -1, True, False)

        # Check if a number is a stepping number
        def is_stepping(s: str) -> bool:
            for i in range(1, len(s)):
                if abs(int(s[i]) - int(s[i - 1])) != 1:
                    return False
            return True

        # Count stepping numbers in the range [low, high]
        count_high = count_less_than_or_equal(high)
        count_low_minus_one = count_less_than_or_equal(low) - (1 if is_stepping(low) else 0)

        return (count_high - count_low_minus_one) % MOD
