class Solution:
    def maxDistance(self, s: str, k: int) -> int:
        n = len(s)
        # Calculate the initial position and max distance without any changes
        x, y = 0, 0
        max_distance = 0
        positions = [(x, y)]  # Store all positions for later use

        for direction in s:
            if direction == 'N':
                y += 1
            elif direction == 'S':
                y -= 1
            elif direction == 'E':
                x += 1
            elif direction == 'W':
                x -= 1
            positions.append((x, y))
            max_distance = max(max_distance, abs(x) + abs(y))

        # If we can't make any changes or the string is empty, return the max distance
        if k == 0 or n == 0:
            return max_distance

        # Calculate the impact of changing each character
        impact = []
        for i in range(n):
            original_x, original_y = positions[i]

            # Get the direction at position i
            original_dir = s[i]

            # Try all possible directions for the change
            for new_dir in ['N', 'S', 'E', 'W']:
                if new_dir == original_dir:
                    continue

                # Calculate the change in position
                dx, dy = 0, 0

                # Remove the effect of the original direction
                if original_dir == 'N':
                    dy = -1
                elif original_dir == 'S':
                    dy = 1
                elif original_dir == 'E':
                    dx = -1
                elif original_dir == 'W':
                    dx = 1

                # Add the effect of the new direction
                if new_dir == 'N':
                    dy += 1
                elif new_dir == 'S':
                    dy -= 1
                elif new_dir == 'E':
                    dx += 1
                elif new_dir == 'W':
                    dx -= 1

                # Calculate new positions and max distance
                new_max_distance = max_distance
                for j in range(i + 1, n + 1):
                    new_x, new_y = positions[j][0] + dx, positions[j][1] + dy
                    new_max_distance = max(new_max_distance, abs(new_x) + abs(new_y))

                # Store the change and its impact
                impact.append((new_max_distance - max_distance, i, new_dir))

        # Sort changes by their impact (descending)
        impact.sort(reverse=True)

        # Apply the top k changes
        changes = {}
        for i in range(min(k, len(impact))):
            _, pos, new_dir = impact[i]
            if pos not in changes:
                changes[pos] = new_dir
            else:
                # If this position is already changed, skip this change
                k += 1
                continue

        # Re-simulate the path with changes
        x, y = 0, 0
        max_distance = 0
        for i, direction in enumerate(s):
            if i in changes:
                direction = changes[i]

            if direction == 'N':
                y += 1
            elif direction == 'S':
                y -= 1
            elif direction == 'E':
                x += 1
            elif direction == 'W':
                x -= 1

            max_distance = max(max_distance, abs(x) + abs(y))

        return max_distance
