def get_partitions(n):
    """Generates all partitions of n."""
    if n == 0:
        yield []
        return
    for i in range(1, n + 1):
        for p in get_partitions(n - i):
            if not p or i <= p[0]:
                yield [i] + p

def get_partitions_list(n):
    """Returns a list of all partitions of n, each as a sorted tuple."""
    partitions = []
    for p in get_partitions(n):
        partitions.append(tuple(sorted(p, reverse=True)))
    return partitions

