    # Group partitions by size (number of parts)
    partitions_by_m = {}
    for p in all_partitions:
        m = len(p)
        if m not in partitions_by_m:
            partitions_by_m[m] = []
        partitions_by_m[m].append(p)

    possible_fixed = [False] * (N * N + 1)
    possible_fixed[0] = True # Base case: empty set of fixed blocks has sum 0

    # Max possible sum of products is N*N
    max_sum_limit = N * N

    for m in partitions_by_m:
        s_partitions = partitions_by_m[m]
        t_partitions = partitions_by_m[m]

        for s in s_partitions:
            for t in t_partitions:
                # Create multiset of products {s_i * t_i} for i=0..m-1
                # Partitions s and t are already sorted decreasingly
                products = []
                for i in range(m):
                    products.append(s[i] * t[i])

                # Compute subset sums of this multiset using DP
                # dp_sums[k] is True if k is a possible subset sum of `products`
                dp_sums = [False] * (max_sum_limit + 1)
                dp_sums[0] = True

                for val in products:
                    # Iterate backwards to avoid using the same element twice in a subset sum
                    for current_sum in range(max_sum_limit, val - 1, -1):
                        if dp_sums[current_sum - val]:
                            dp_sums[current_sum] = True

                # Add these subset sums to the set of all possible fixed counts
