class Solution:
    def minGroupsForValidAssignment(self, nums: List[int]) -> int:
        # Count the frequency of each value
        freq_map = {}
        for num in nums:
            freq_map[num] = freq_map.get(num, 0) + 1

        frequencies = list(freq_map.values())
        min_freq = min(frequencies)

        # Try all possible group sizes from min_freq down to 1
        for k in range(min_freq, 0, -1):
            valid = True
            total_groups = 0

            for freq in frequencies:
                # Calculate how many groups are needed for this frequency
                quotient, remainder = divmod(freq, k)

                # If remainder is too large, we can't form valid groups
                if remainder > quotient:
                    valid = False
                    break

                # Calculate minimum number of groups needed for this frequency
                groups_needed = quotient
                if remainder > 0:
                    # Some groups need to have size k+1, adding one element to some groups of size k
                    groups_needed = quotient + 1 - remainder

                total_groups += groups_needed

            if valid:
                return total_groups

