My approach:
1. Use dynamic programming with interval scheduling
2. Sort intervals by end time for efficient DP
3. For each interval, find the latest non-overlapping interval before it
4. Use DP to find maximum weight for choosing up to k intervals
5. Backtrack to find all solutions with maximum weight
6. Return the lexicographically smallest solution

```python
class Solution:
    def maximumWeight(self, intervals: List[List[int]]) -> List[int]:
        n = len(intervals)

        # Add index to each interval and sort by end time
        indexed = [(intervals[i][0], intervals[i][1], intervals[i][2], i) for i in range(n)]
        indexed.sort(key=lambda x: x[1])

        # For each interval, find the last non-overlapping interval
        last_non_overlapping = [-1] * n
        for i in range(n):
            for j in range(i - 1, -1, -1):
                if indexed[j][1] <= indexed[i][0]:
                    last_non_overlapping[i] = j
                    break

        # DP to find maximum weight
        # dp[i][j] = max weight using first i intervals and choosing exactly j intervals
        NEG_INF = -float('inf')
        dp = [[NEG_INF] * 5 for _ in range(n + 1)]

        # Base case: choosing 0 intervals from first i intervals gives weight 0
        for i in range(n + 1):
            dp[i][0] = 0

        for i in range(1, n + 1):
            for j in range(1, 5):
                # Don't take interval i-1
                dp[i][j] = dp[i-1][j]

                # Take interval i-1
                prev_idx = last_non_overlapping[i-1]
                if prev_idx == -1:
                    # No previous non-overlapping interval
                    if j == 1:
                        dp[i][j] = max(dp[i][j], indexed[i-1][2])
                else:
                    if dp[prev_idx + 1][j-1] != NEG_INF:
                        dp[i][j] = max(dp[i][j], dp[prev_idx + 1][j-1] + indexed[i-1][2])

        # Find maximum weight
        max_weight = 0
        for j in range(1, 5):
            max_weight = max(max_weight, dp[n][j])

        # Find all possible solutions with maximum weight
        all_solutions = set()

        def backtrack(i, j, weight, indices):
            if j == 0 and weight == 0:
                all_solutions.add(tuple(sorted(indices)))
                return

            if i == 0 or j < 0 or weight < 0:
                return

            # Try not taking interval i-1
            if dp[i-1][j] == weight:
                backtrack(i-1, j, weight, indices)

            # Try taking interval i-1
            interval_weight = indexed[i-1][2]
            prev_idx = last_non_overlapping[i-1]

            if prev_idx == -1:
                # No previous non-overlapping interval
                if j == 1 and weight == interval_weight:
                    backtrack(0, 0, 0, indices + [indexed[i-1][3]])
            else:
                prev_weight = weight - interval_weight
                if dp[prev_idx + 1][j-1] == prev_weight:
                    backtrack(prev_idx + 1, j-1, prev_weight, indices + [indexed[i-1][3]])

        # Try all possible numbers of intervals
        for j in range(1, 5):
            if dp[n][j] == max_weight:
                backtrack(n, j, max_weight, [])

        # Return lexicographically smallest solution
        all_solutions = sorted(list(all_solutions))
        return list(all_solutions[0])
