        memo = {}
        MOD = 10**9 + 7
        MAX_JUMP = 31  # 2^31 is more than 10^9

        def dfs(curr, jump, prev_down):
            if jump > MAX_JUMP:  # Limit the jump value
                return 0

            if (curr, jump, prev_down) in memo:
                return memo[(curr, jump, prev_down)]

            ways = 1 if curr == k else 0

            # Option 1: Go down
            if curr > 0 and not prev_down:
                ways = (ways + dfs(curr - 1, jump, True)) % MOD

            # Option 2: Go up
            ways = (ways + dfs(curr + 2**jump, jump + 1, False)) % MOD

            memo[(curr, jump, prev_down)] = ways
            return ways

