class Solution:
    def longestPalindromicSubsequence(self, s: str, k: int) -> int:
        n = len(s)
        if n == 0:
            return 0

        # Initialize DP table: dp[i][j][x] is the max length of palindromic subsequence in s[i..j] with cost <=x
        dp = [[[0] * (k + 1) for _ in range(n)] for __ in range(n)]

        # Base case: single character
        for i in range(n):
            for x in range(k + 1):
                dp[i][i][x] = 1

        # Precompute cost to change a character
        def cost_change(a, b_char):
            b = ord(b_char)
            a_val = ord(a)
            diff = (b - a_val) % 26
            return min(diff, 26 - diff)

        # Fill DP table in bottom-up manner
        for length in range(2, n + 1):  # length of substring
            for i in range(n - length + 1):
                j = i + length - 1
                for x in range(k + 1):
                    # Option 1: exclude either s[i] or s[j]
                    best = max(dp[i + 1][j][x], dp[i][j - 1][x])

                    # Option 2: consider all possible target characters for s[i] and s[j]
                    for c in range(26):
                        target_char = chr(ord('a') + c)
                        cost_i = cost_change(s[i], target_char)
                        cost_j = cost_change(s[j], target_char)
                        total_cost = cost_i + cost_j

                        if x >= total_cost:
                            if i + 1 <= j - 1:
                                inner_length = dp[i + 1][j - 1][x - total_cost]
                            else:
                                inner_length = 0
                            candidate = inner_length + 2
                            if candidate > best:
                                best = candidate
                    dp[i][j][x] = best

        return dp[0][n - 1][k]
