class Solution:
    def maxTotalReward(self, rewardValues: List[int]) -> int:
        # Sort rewards in ascending order
        sorted_rewards = sorted(rewardValues)

        # Memoization to avoid redundant calculations
        memo = {}

        def dp(i, x):
            # Base case: If all rewards are considered, return the current total
            if i == len(sorted_rewards):
                return x

            # If this state has been computed before, return the memoized result
            if (i, x) in memo:
                return memo[(i, x)]

            # Option 1: Skip the current reward
            skip = dp(i + 1, x)

            # Option 2: Include the current reward if eligible
            take = 0
            if sorted_rewards[i] > x:
                take = dp(i + 1, x + sorted_rewards[i])

            # Memoize and return the better option
            memo[(i, x)] = max(skip, take)
            return memo[(i, x)]

        # Start the DP calculation
        return dp(0, 0)
