        MOD = 10**9 + 7

        def subtract_one(s):
            if s == '0':
                return '0'
            digits = list(s)
            i = len(digits) - 1
            while i >= 0 and digits[i] == '0':
                digits[i] = '9'
                i -= 1
            if i == -1:
                return '0'
            digits[i] = str(int(digits[i]) - 1)
            if digits[0] == '0' and len(digits) > 1:
                digits = digits[1:]
            return ''.join(digits)

