            if s == '0':
                return 0
            digits = list(map(int, s))
            n = len(digits)

            from functools import lru_cache

            @lru_cache(maxsize=None)
            def dp(pos, prev_digit, leading_zero, tight):
                if pos == n:
                    return 0 if leading_zero else 1
                res = 0
                upper = digits[pos] if tight else 9
                for d in range(0, upper + 1):
                    new_tight = tight and (d == upper)
                    if leading_zero:
                        if d == 0:
                            res += dp(pos + 1, -1, True, new_tight)
                        else:
                            res += dp(pos + 1, d, False, new_tight)
                    else:
                        if abs(d - prev_digit) != 1:
                            continue
                        res += dp(pos + 1, d, False, new_tight)
                    res %= MOD
                return res % MOD

            return dp(0, -1, True, True)

        high_count = helper(high)
        low_minus_one = subtract_one(low)
        low_count = helper(low_minus_one)
        return (high_count - low_count + MOD) % MOD
