    def maxPartitionsAfterOperations(self, s: str, k: int) -> int:
        memo = {}

        def max_partitions(i, mask, changed):
            if i == len(s):
                return 1

            if (i, mask, changed) in memo:
                return memo[(i, mask, changed)]

            c = ord(s[i]) - ord('a')
            bit = 1 << c

            distinct = bin(mask).count('1')

