            if mask & bit or distinct < k:
                result = max_partitions(i + 1, mask | bit, changed)
            else:
                # Start a new partition
                result = 1 + max_partitions(i + 1, bit, changed)

            # If we haven't changed a character yet, try changing the current one
            if not changed:
                for new_c in range(26):
