class Solution:
    def maxBalancedSubsequenceSum(self, nums: List[int]) -> int:
        n = len(nums)

        # If all elements are non-positive, return the largest element
        if all(num <= 0 for num in nums):
            return max(nums)

        # SortedDict to map val to maximum dp
        sd = SortedDict()

