            if curr_dp <= 0:  # Skip if it doesn't increase our dp
                continue

            if v in sd:
                sd[v] = max(sd[v], curr_dp)
            else:
                sd[v] = curr_dp

            # Ensure our invariant
            keys_to_remove = []
            idx = sd.bisect_right(v)
            while idx < len(sd):
                key, val = sd.peekitem(idx)
                if val <= curr_dp:
                    keys_to_remove.append(key)
                    idx += 1
                else:
                    break

            for key in keys_to_remove:
                del sd[key]

