class Solution:
    def maxBalancedSubsequenceSum(self, nums: List[int]) -> int:
        n = len(nums)

        # Define differences array
        diffs = [nums[i] - i for i in range(n)]

        # Map to store (diff, max_sum) pairs
        from sortedcontainers import SortedDict
        sd = SortedDict()

        for i in range(n):
            # Current difference value
            diff = diffs[i]

            # Find the max sum of a balanced subsequence that can include current element
            curr_max = nums[i]

            # Find the position where diff would be inserted
            pos = sd.bisect_right(diff)

            # If there are previous valid subsequences, get the max sum
            if pos > 0:
                prev_diff = sd.keys()[pos-1]
                curr_max = max(curr_max, sd[prev_diff] + nums[i])

            # Update the dictionary with our current diff
            if diff in sd:
                sd[diff] = max(sd[diff], curr_max)
            else:
                sd[diff] = curr_max

            # Remove all subsequent keys that have lower or equal sums
            # (we always prefer our entry over them for future extensions)
            to_remove = []
            for next_diff in list(sd.keys())[sd.bisect_right(diff):]:
                if sd[next_diff] <= curr_max:
                    to_remove.append(next_diff)
                else:
                    break

            for key in to_remove:
                del sd[key]

        # If dictionary is empty, return max element (single element subsequence)
        if not sd:
            return max(nums)

        return max(sd.values())
