def solve():
    n, k = map(int, input().split())

    if k == 1:
        print("Yes")
        return

    adj = [[] for _ in range(n * k + 1)]
    for _ in range(n * k - 1):
        u, v = map(int, input().split())
        adj[u].append(v)
        adj[v].append(u)

    used = [False] * (n * k + 1)

    def find_paths_from(start):
        # Find all paths of length k starting from 'start'
        paths = []

        def dfs(current, parent, path):
            if len(path) == k:
                paths.append(path[:])
                return

            for neighbor in adj[current]:
                if neighbor != parent and not used[neighbor]:
                    path.append(neighbor)
                    dfs(neighbor, current, path)
                    path.pop()

        dfs(start, -1, [start])
        return paths

    def solve_recursive(paths_remaining):
        if paths_remaining == 0:
            return True

        # Find the first unused vertex
        start = -1
        for v in range(1, n * k + 1):
            if not used[v]:
                start = v
                break

        if start == -1:
            return False

        # Try all possible paths starting from 'start'
        possible_paths = find_paths_from(start)

        for path in possible_paths:
            # Mark all vertices in this path as used
            for v in path:
                used[v] = True

            # Recursively solve for the remaining paths
            if solve_recursive(paths_remaining - 1):
                return True

            # Backtrack: unmark the vertices
            for v in path:
                used[v] = False

        return False

    if solve_recursive(n):
        print("Yes")
    else:
        print("No")

