    def minimumSubstringsInPartition(self, s: str) -> int:
        n = len(s)

        # Helper function to check if a substring is balanced
        def is_balanced(start, end):
            if start == end:
                return False

            count = {}
            for i in range(start, end):
                count[s[i]] = count.get(s[i], 0) + 1

            # Check if all characters have the same count
            counts = list(count.values())
            return all(c == counts[0] for c in counts)

        # dp[i] = minimum number of balanced substrings to partition s[0:i]
        dp = [float('inf')] * (n + 1)
        dp[0] = 0

        for i in range(1, n + 1):
            for j in range(i):
                if is_balanced(j, i):
                    dp[i] = min(dp[i], dp[j] + 1)

        return dp[n]
