    """Rotate a shape by a given rotation (0, 1, 2, or 3 times 90 degrees clockwise)."""
    if rotation == 0:
        return shape
    elif rotation == 1:  # 90 degrees clockwise
        return [(j, 3-i) for i, j in shape]
    elif rotation == 2:  # 180 degrees
        return [(3-i, 3-j) for i, j in shape]
    elif rotation == 3:  # 270 degrees clockwise
        return [(3-j, i) for i, j in shape]

def normalize_shape(shape):
    """Normalize a shape to have its top-left corner at (0, 0)."""
    if not shape:
        return shape
    min_i = min(i for i, j in shape)
    min_j = min(j for i, j in shape)
    return [(i - min_i, j - min_j) for i, j in shape]

def generate_all_rotations_of_shape(shape):
    """Generate all possible rotations of a shape."""
    all_rotations = []
    for r in range(4):
