Looking at this problem, I need to count numbers in the range [start, finish] that:
1. End with string s (s is a suffix)
2. Have all digits ≤ limit

Key insight: If a number x ends with s, then x = prefix * 10^len(s) + int(s), where prefix ≥ 0.

Here's my approach:
1. First check if s itself has all digits ≤ limit
2. Find the valid range for prefixes
3. Count how many prefixes have all digits ≤ limit using digit DP

```python
class Solution:
    def numberOfPowerfulInt(self, start: int, finish: int, limit: int, s: str) -> int:
        s_val = int(s)
        s_len = len(s)

        # Check if s itself has all digits <= limit
        for digit in s:
            if int(digit) > limit:
                return 0

        # Function to count numbers from 1 to n with all digits <= limit
        def count_from_1_to_n(n):
            if n <= 0:
                return 0

            s = str(n)
            m = len(s)

            from functools import lru_cache

            @lru_cache(None)
            def dp(pos, tight, started):
                if pos == m:
                    return 1 if started else 0

                res = 0
                max_digit = int(s[pos]) if tight else 9

                if not started:
                    # Leading zero
                    res += dp(pos + 1, False, False)
                    # Start with 1 to min(max_digit, limit)
                    for digit in range(1, min(max_digit, limit) + 1):
                        res += dp(pos + 1, tight and digit == int(s[pos]), True)
                else:
                    # Continue with 0 to min(max_digit, limit)
                    for digit in range(0, min(max_digit, limit) + 1):
                        res += dp(pos + 1, tight and digit == int(s[pos]), True)

                return res

            return dp(0, True, False)

        count = 0

        # Check if s itself is valid (prefix = 0 or empty)
        if start <= s_val <= finish:
            count += 1

        # Count numbers with prefix >= 1
        if finish >= 10**s_len + s_val:
            min_prefix = 1
            if start > s_val:
                min_prefix = max(1, (start - s_val + 10**s_len - 1) // 10**s_len)

            max_prefix = (finish - s_val) // 10**s_len

            if min_prefix <= max_prefix:
                count += count_from_1_to_n(max_prefix) - count_from_1_to_n(min_prefix - 1)

        return count
