class Solution:
    def minOperations(self, nums: List[int], target: int) -> int:
        # Count the frequency of each bit position
        bit_count = [0] * 31
        for num in nums:
            bit = 0
            while (1 << bit) <= num:
                if num & (1 << bit):
                    bit_count[bit] += 1
                bit += 1

        # Total sum of nums
        total = sum(nums)
        if total < target:
            return -1  # Impossible case

        operations = 0
        extra = 0  # Extra bits that we can use

        for bit in range(31):
            # Check if we need this bit for target
            need_bit = (target & (1 << bit)) > 0

            if need_bit:
                # Use an available bit if we have one
                if bit_count[bit] > 0:
                    bit_count[bit] -= 1
                    extra += bit_count[bit]  # Remaining bits are extra
                elif extra > 0:
                    # Use an extra bit from previous positions
                    extra -= 1
                else:
                    # We need to break down higher bits
                    found = False
                    for higher_bit in range(bit + 1, 31):
                        if bit_count[higher_bit] > 0:
                            # Found a higher bit to break down
                            bit_count[higher_bit] -= 1
                            operations += higher_bit - bit
                            # When breaking down, we get 2^(higher_bit-bit-1) extra bits
                            # Plus we already used one bit for the current position
                            extra = (1 << (higher_bit - bit)) - 1
                            found = True
                            break

                    if not found:
                        return -1  # Impossible case
            else:
