class Solution:
    def minOperations(self, nums: List[int], target: int) -> int:
        if sum(nums) < target:
            return -1

        # Count of each power of 2 in nums
        bit_count = [0] * 31
        for num in nums:
            for i in range(31):
                if num == (1 << i):
                    bit_count[i] += 1
                    break

        operations = 0
        extra = 0  # Extra bits we have after matching the target

        for i in range(31):
            if target & (1 << i):  # Target needs 2^i
                if bit_count[i] > 0:
                    bit_count[i] -= 1
                elif extra > 0:
                    extra -= 1
                else:
                    # Find the smallest higher bit that's available
                    j = i + 1
                    while j < 31 and bit_count[j] == 0:
                        j += 1

                    if j == 31:
                        return -1

                    operations += j - i
                    bit_count[j] -= 1
                    extra += (1 << (j - i)) - 1  # We get 2^(j-i) of bit i, but we use one for the target

            extra += bit_count[i]  # Add leftover bits to extra

        return operations
