class Solution:
    def maxTotalReward(self, rewardValues: List[int]) -> int:
        rewardValues.sort()

        possible = {0}
        for reward in rewardValues:
            new_sums = {s + reward for s in possible if reward > s}
            possible.update(new_sums)

