class Solution:
    def countGoodIntegers(self, n: int, k: int) -> int:
        from itertools import permutations
        from math import factorial

        def can_form_k_palindrome(digit_counts):
            # Check if we can form a palindrome
            odd_count = sum(1 for count in digit_counts if count % 2 == 1)
            if n % 2 == 0 and odd_count > 0:
                return False
            if n % 2 == 1 and odd_count != 1:
                return False

            # Build digit list
            digits = []
            for digit, count in enumerate(digit_counts):
                digits.extend([str(digit)] * count)

            # Try to form palindromes and check divisibility by k
            seen = set()
            for perm in permutations(digits):
                if perm[0] == '0':
                    continue
                if perm == perm[::-1]:
                    num_str = ''.join(perm)
                    if num_str not in seen:
                        seen.add(num_str)
                        if int(num_str) % k == 0:
                            return True

            return False

        def count_valid_numbers(digit_counts):
            # Count n-digit numbers with given digit frequency
            total = factorial(n)
            for count in digit_counts:
                if count > 0:
                    total //= factorial(count)

            # Subtract those with leading zero
            if digit_counts[0] > 0:
                invalid = factorial(n-1)
                for i, count in enumerate(digit_counts):
                    if i == 0 and count > 1:
                        invalid //= factorial(count - 1)
                    elif i > 0 and count > 0:
                        invalid //= factorial(count)
                total -= invalid

            return total

        result = 0

        # Generate all possible digit frequency distributions
        def generate_distributions(remaining, digit, current):
            nonlocal result

            if digit == 10:
                if remaining == 0:
                    if can_form_k_palindrome(current):
                        result += count_valid_numbers(current)
                return

            for count in range(remaining + 1):
                generate_distributions(remaining - count, digit + 1, current + (count,))

        generate_distributions(n, 0, ())

        return result
