from typing import List

class Solution:
    def lenOfVDiagonal(self, grid: List[List[int]]) -> int:
        n = len(grid)
        if n == 0:
            return 0
        m = len(grid[0])
        max_len = 0
        directions = [ (1,1), (1,-1), (-1,-1), (-1,1) ]

        def compute_straight(i, j, dx, dy):
            if grid[i][j] != 1:
                return 0
            length = 1
            expected = 2
            x, y = i + dx, j + dy
            while 0 <= x < n and 0 <= y < m:
                if grid[x][y] == expected:
                    length += 1
                    expected = 0 if expected == 2 else 2
                    x += dx
                    y += dy
                else:
                    break
            return length

        def compute_turn(x, y, dx, dy, start_s):
            # Calculate the length of the sequence starting at (x,y) in direction (dx, dy)
            # following the pattern starting from start_s
            if start_s % 2 == 1:
                current_val = 2
            else:
                current_val = 0
            if grid[x][y] != current_val:
                return 0
            current_len = 1
            x += dx
            y += dy
            # Now check subsequent cells
            while 0 <= x < n and 0 <= y < m:
                next_s = start_s + current_len
                needed = 2 if (next_s + 1) % 2 == 1 else 0
                if grid[x][y] == needed:
                    current_len += 1
                    x += dx
                    y += dy
                else:
                    break
            return current_len

        for i in range(n):
            for j in range(m):
                if grid[i][j] == 1:
                    for dx, dy in directions:
                        straight_len = compute_straight(i, j, dx, dy)
                        if straight_len > max_len:
                            max_len = straight_len
                        # Calculate rotated direction (clockwise 90)
                        ddx, ddy = dy, -dx
                        for L in range(1, straight_len + 1):
                            x = i + dx * (L - 1)
                            y = j + dy * (L - 1)
                            if not (0 <= x < n and 0 <= y < m):
                                continue
                            # Determine required value at s = L
                            required_val = 2 if (L % 2 == 1) else 0
                            if grid[x][y] != required_val:
                                continue
                            # Calculate the turn part
                            turn_len = compute_turn(x, y, ddx, ddy, L)
                            total = L + turn_len
                            if total > max_len:
                                max_len = total
        return max_len
