        from functools import lru_cache

        @lru_cache(None)
        def dp(arr):
            n = len(arr)
            if n < 3:
                return max(arr)

            min_cost = float('inf')
            # Try all three pairs from the first three elements
            for i, j in [(0, 1), (0, 2), (1, 2)]:
                cost = max(arr[i], arr[j])
                # Create new array without elements at indices i and j
                new_arr = [arr[k] for k in range(n) if k != i and k != j]
                min_cost = min(min_cost, cost + dp(tuple(new_arr)))

            return min_cost

        return dp(tuple(nums))
