class Solution:
    def numberOfWays(self, s: str, t: str, k: int) -> int:
        MOD = 10**9 + 7
        n = len(s)

        # Check if t is a rotation of s
        s_doubled = s + s
        positions = []
        for i in range(n):
            if s_doubled[i:i+n] == t:
                positions.append(i)

        if not positions:
            return 0

        # Matrix exponentiation to compute the number of ways
        def matrix_mul(A, B):
            C = [[0] * n for _ in range(n)]
            for i in range(n):
                for j in range(n):
                    for k in range(n):
                        C[i][j] = (C[i][j] + A[i][k] * B[k][j]) % MOD
            return C

        def matrix_pow(A, p):
            result = [[1 if i == j else 0 for j in range(n)] for i in range(n)]
            while p > 0:
                if p & 1:
                    result = matrix_mul(result, A)
                A = matrix_mul(A, A)
                p >>= 1
            return result

        # Create transition matrix M
        M = [[0] * n for _ in range(n)]
        for i in range(n):
            for j in range(1, n):
                M[i][(i + j) % n] = 1

        # Calculate M^k
        M_k = matrix_pow(M, k)

        # Sum up the ways to reach target positions
        total_ways = 0
        for pos in positions:
            total_ways = (total_ways + M_k[0][pos]) % MOD

        return total_ways
