        for r in range(n):
            for c in range(m):
                r_next, c_next = r - 1, c - 1

                # State 1 (2,0,2...): grid[r][c] must be 2
                if grid[r][c] == 2:
                    if 0 <= r_next < n and 0 <= c_next < m:
                        # Next must match 0,2,0... (State 2)
                        len_cont[2][r][c][1] = 1 + len_cont[2][r_next][c_next][2]
                    else:
                        len_cont[2][r][c][1] = 1
                # State 2 (0,2,0...): grid[r][c] must be 0
                if grid[r][c] == 0:
                    if 0 <= r_next < n and 0 <= c_next < m:
                        # Next must match 2,0,2... (State 1)
                        len_cont[2][r][c][2] = 1 + len_cont[2][r_next][c_next][1]
                    else:
                        len_cont[2][r][c][2] = 1

        # Calculate len_cont for dir 3 (-1,1), iterate r:0->n-1, c:m-1->0
        for r in range(n):
            for c in range(m-1, -1, -1):
                r_next, c_next = r - 1, c + 1

                # State 1 (2,0,2...): grid[r][c] must be 2
                if grid[r][c] == 2:
                    if 0 <= r_next < n and 0 <= c_next < m:
                        # Next must match 0,2,0... (State 2)
                        len_cont[3][r][c][1] = 1 + len_cont[3][r_next][c_next][2]
                    else:
                        len_cont[3][r][c][1] = 1
                # State 2 (0,2,0...): grid[r][c] must be 0
                if grid[r][c] == 0:
                    if 0 <= r_next < n and 0 <= c_next < m:
                        # Next must match 2,0,2... (State 1)
                        len_cont[3][r][c][2] = 1 + len_cont[3][r_next][c_next][1]
                    else:
                        len_cont[3][r][c][2] = 1


        # Combine segments at potential turn points (r,c)
        for r in range(n):
