                        (r_next_out, c_next_out) = (r + dr_out, c + dc_out)

                        L_out_from_next = 0

                        # The cell (r_next_out, c_next_out) corresponds to sequence index L_in
                        # It must match expected_value(L_in) and start the continuation sequence.

                        if 0 <= r_next_out < n and 0 <= c_next_out < m:
                            req_val_at_next = expected_value(L_in)

                            if req_val_at_next == 2 and grid[r_next_out][c_next_out] == 2:
                                # The continuation sequence starting at (r_next_out, c_next_out) is 2,0,2,...
                                # The length of this sequence starting at (r_next_out, c_next_out) is len_cont[dir_out][r_next_out][c_next_out][1]
                                L_out_from_next = len_cont[dir_out][r_next_out][c_next_out][1]

                            elif req_val_at_next == 0 and grid[r_next_out][c_next_out] == 0:
                                # The continuation sequence starting at (r_next_out, c_next_out) is 0,2,0,...
                                # The length of this sequence starting at (r_next_out, c_next_out) is len_cont[dir_out][r_next_out][c_next_out][2]
                                L_out_from_next = len_cont[dir_out][r_next_out][c_next_out][2]

                            # Note: expected(L_in) cannot be 1 if L_in > 0.


                        # Total length = length of first part + length of second part (excluding the shared turn point)
                        # L_in is the length of the first part ending at (r,c)
                        # L_out_from_next is the length of the second part starting *from the cell after* (r,c)
                        total_len = L_in + L_out_from_next
                        max_len = max(max_len, total_len)

        return max_len
