class Solution:
    def canTraverseAllPairs(self, nums: List[int]) -> bool:
        n = len(nums)
        if n == 1:
            return True

        # Union-Find
        parent = list(range(n))

        def find(x):
            if parent[x] != x:
                parent[x] = find(parent[x])
            return parent[x]

        def union(x, y):
            px, py = find(x), find(y)
            if px != py:
                parent[px] = py

        # Find prime factors for each number
        def get_prime_factors(num):
            factors = set()
            d = 2
            while d * d <= num:
                while num % d == 0:
                    factors.add(d)
                    num //= d
                d += 1
            if num > 1:
                factors.add(num)
            return factors

        # Group indices by prime factors
        prime_to_indices = {}
        for i, num in enumerate(nums):
            if num == 1:
                return False  # 1 can't connect to anything
            factors = get_prime_factors(num)
            for factor in factors:
                if factor not in prime_to_indices:
                    prime_to_indices[factor] = []
                prime_to_indices[factor].append(i)

        # Union indices that share prime factors
        for indices in prime_to_indices.values():
            for i in range(1, len(indices)):
                union(indices[0], indices[i])

        # Check if all indices are in the same component
        root = find(0)
        for i in range(1, n):
            if find(i) != root:
                return False

        return True
