class Solution:
    def longestPalindromicSubsequence(self, s: str, k: int) -> int:
        n = len(s)

        def cost(a, b):
            diff = abs(ord(a) - ord(b))
            return min(diff, 26 - diff)

        memo = {}

        def dp(i, j, ops):
            if i > j:
                return 0
            if i == j:
                return 1

            if (i, j, ops) in memo:
                return memo[(i, j, ops)]

            # Option 1: Skip one of the ends
            result = max(dp(i+1, j, ops), dp(i, j-1, ops))

            # Option 2: Try to match the ends
            for c in 'abcdefghijklmnopqrstuvwxyz':
                cost_to_match = cost(s[i], c) + cost(s[j], c)
                if cost_to_match <= ops:
                    result = max(result, 2 + dp(i+1, j-1, ops - cost_to_match))

            memo[(i, j, ops)] = result
            return result

        return dp(0, n-1, k)
