class Solution:
    def minMaxWeight(self, n: int, edges: List[List[int]], threshold: int) -> int:
        from collections import deque
        from itertools import combinations

        def can_reach_node0(adj_list):
            # Check if node 0 is reachable from all other nodes
            # Build reverse graph and BFS from node 0
            reverse_graph = [[] for _ in range(n)]
            for u in range(n):
                for v in adj_list[u]:
                    reverse_graph[v].append(u)

            visited = [False] * n
            queue = deque([0])
            visited[0] = True

            while queue:
                u = queue.popleft()
                for v in reverse_graph[u]:
                    if not visited[v]:
                        visited[v] = True
                        queue.append(v)

            return all(visited)

        def is_feasible(max_weight):
            # Build adjacency list with edges of weight <= max_weight
            adj_list = [[] for _ in range(n)]
            edge_weights = {}

            for u, v, w in edges:
                if w <= max_weight:
                    adj_list[u].append(v)
                    if u not in edge_weights:
                        edge_weights[u] = {}
                    edge_weights[u][v] = w

            # Quick check: if node 0 isn't reachable with all valid edges
            if not can_reach_node0(adj_list):
                return False

            # Find nodes with out-degree > threshold
            problematic_nodes = []
            for u in range(n):
                if len(adj_list[u]) > threshold:
                    problematic_nodes.append(u)

            if not problematic_nodes:
                return True

            # For small instances, try all combinations
            if len(problematic_nodes) <= 5 and all(len(adj_list[node]) <= 10 for node in problematic_nodes):
                def backtrack(idx):
                    if idx == len(problematic_nodes):
                        return can_reach_node0(current_adj)

                    node = problematic_nodes[idx]
                    neighbors = adj_list[node]

                    for selected in combinations(neighbors, threshold):
                        current_adj[node] = list(selected)
                        if backtrack(idx + 1):
                            return True

                    current_adj[node] = neighbors
                    return False

                current_adj = [adj_list[i][:] for i in range(n)]
                return backtrack(0)

            else:
                # For large instances, use greedy heuristic
                # Keep edges with smallest weights
                new_adj_list = [[] for _ in range(n)]

                for u in range(n):
                    if u in problematic_nodes:
                        neighbors = adj_list[u]
                        neighbors_sorted = sorted(neighbors, 
                                                key=lambda v: edge_weights[u][v])
                        new_adj_list[u] = neighbors_sorted[:threshold]
                    else:
                        new_adj_list[u] = adj_list[u][:]

                return can_reach_node0(new_adj_list)

        # Binary search on the maximum weight
        unique_weights = sorted(set(w for _, _, w in edges))
        left, right = 0, len(unique_weights) - 1
        result = -1

        while left <= right:
            mid = (left + right) // 2
            if is_feasible(unique_weights[mid]):
                result = unique_weights[mid]
                right = mid - 1
            else:
                left = mid + 1

        return result
