class Solution:
    def countGoodIntegers(self, n: int, k: int) -> int:
        def can_form_palindrome(counts):
            odd_count = sum(1 for count in counts.values() if count % 2 == 1)
            return odd_count <= 1

        # Check if a multiset can form a k-palindromic number
        def is_good(counts):
            if not can_form_palindrome(counts):
                return False

            # Create all possible palindromes and check if any is divisible by k
            return check_palindrome(counts, 0, 0, [0] * n)

        # Build palindromes and check divisibility by k
        def check_palindrome(counts, pos, used, curr):
            if pos >= (n + 1) // 2:
                number = int(''.join(map(str, curr)))
                return number % k == 0

            for digit in range(10):
                # Skip leading zeros
                if pos == 0 and digit == 0:
                    continue

                if counts.get(digit, 0) >= (2 if pos != n // 2 else 1):
                    # Use the digit at current position and its mirror position
                    counts[digit] = counts.get(digit, 0) - (2 if pos != n // 2 else 1)
                    curr[pos] = digit
                    if pos != n // 2:  # Not the middle position
                        curr[n - 1 - pos] = digit

                    if check_palindrome(counts, pos + 1, used + (2 if pos != n // 2 else 1), curr):
                        return True

                    # Backtrack
                    counts[digit] = counts.get(digit, 0) + (2 if pos != n // 2 else 1)

            return False

        # Generate all multisets with n digits
        def generate_multisets(remaining, min_digit, counts, result):
            if remaining == 0:
                if is_good(counts.copy()):
                    result.add(tuple(counts.get(i, 0) for i in range(10)))
                return

            for digit in range(min_digit, 10):
                counts[digit] = counts.get(digit, 0) + 1
                generate_multisets(remaining - 1, digit, counts, result)
                counts[digit] -= 1
                if counts[digit] == 0:
                    del counts[digit]

        # Get all good multisets
        good_multisets = set()
        generate_multisets(n, 0, {}, good_multisets)

        # Calculate the number of integers for each good multiset
        count = 0
        for multiset in good_multisets:
            # Calculate multinomial coefficient
            ways = 1
            remaining = n
            for digit_count in multiset:
                # Choose digit_count positions from remaining
                for i in range(1, digit_count + 1):
                    ways *= remaining - i + 1
                    ways //= i
                remaining -= digit_count

            # Subtract arrangements with leading zeros
            if multiset[0] > 0:
                zero_leading_ways = 1
                remaining = n - 1
                for i, digit_count in enumerate(multiset):
                    if i == 0:
                        digit_count -= 1

                    for j in range(1, digit_count + 1):
                        zero_leading_ways *= remaining - j + 1
                        zero_leading_ways //= j

                    remaining -= digit_count

                ways -= zero_leading_ways

            count += ways

        return count
