                cost = 0 if remainder == 0 else (lcmd - remainder)
                subset_costs.append( (cost, idx) )
            # sort and store top 5 candidates
            subset_costs.sort()
            subset_masks[mask]['candidates'] = subset_costs[:5]

        # Generate all partitions of target elements (indices)
        def partitionhelper(elements):
            if not elements:
                return []
            first, rest = elements[0], elements[1:]
            ps = partitionhelper(rest)
            if not ps:
                return [[[first]]]
            new_ps = []
            # Add 'first' to each subset in each partition of rest
            for p in ps:
                # Add to existing subsets
                for i in range(len(p)):
                    new_p = [s.copy() for s in p]
                    new_p[i].append(first)
                    new_ps.append(new_p)
                # Add new subset with 'first'
                new_p = [s.copy() for s in p]
                new_p.append([first])
                new_ps.append(new_p)
            return new_ps

        elements = list(range(t_len))
        all_partitions = partitionhelper(elements)
        if not all_partitions:
            all_partitions = [[]]

        # Convert partitions into masks
        all_partition_masks = []
        for p in all_partitions:
            mask_list = []
            for subset in p:
                mask = 0
                for elem in subset:
                    mask |= (1 << elem)
                mask_list.append(mask)
            all_partition_masks.append(mask_list)

        min_total = float('inf')
        # Iterate all partitions
        for partition in all_partition_masks:
            k = len(partition)
            candidate_lists = []
            valid = True
            for subset_mask in partition:
                if subset_mask not in subset_masks:
                    valid = False
                    break
                candidate_lists.append(subset_masks[subset_mask]['candidates'])
            if not valid:
                continue
            # Check if k <= n
            if k > n:
                continue
            # Generate all combinations of candidates
            for combo in product(*candidate_lists):
                indices = [c[1] for c in combo]
                if len(set(indices)) == k:
                    total_cost = sum(c[0] for c in combo)
                    if total_cost < min_total:
