class Solution:
    def maxSubstringLength(self, s: str, k: int) -> bool:
        n = len(s)
        if k == 0:
            return True

        # Find first and last occurrence of each character
        first_occ = {}
        last_occ = {}
        for i, char in enumerate(s):
            if char not in first_occ:
                first_occ[char] = i
            last_occ[char] = i

        # Find all special substrings
        special = []

        for start in range(n):
            seen_chars = set()
            for end in range(start, n):
                if end - start + 1 == n:  # Skip entire string
                    continue

                seen_chars.add(s[end])

                # Check if substring s[start:end+1] is special
                is_special = True
                for char in seen_chars:
                    if first_occ[char] < start or last_occ[char] > end:
                        is_special = False
