class Solution:
    def numberOfBeautifulIntegers(self, low: int, high: int, k: int) -> int:
        def count_beautiful_up_to(num):
            num_str = str(num)
            n = len(num_str)

            memo = {}

            def dp(pos, tight, even_count, odd_count, remainder, started):
                if pos == n:
                    return 1 if started and even_count == odd_count and even_count > 0 and remainder == 0 else 0

                key = (pos, tight, even_count, odd_count, remainder, started)
                if key in memo:
                    return memo[key]

                ans = 0

                # If not started, we can choose not to include any digit at this position
                if not started:
                    ans += dp(pos + 1, False, 0, 0, 0, False)

                # Determine the range of digits we can use
                start_digit = 0 if started else 1
                limit = int(num_str[pos]) if tight else 9

                for digit in range(start_digit, limit + 1):
                    new_tight = tight and digit == limit

                    # Update the count of even and odd digits
                    new_even_count = even_count + (1 if digit % 2 == 0 else 0)
                    new_odd_count = odd_count + (1 if digit % 2 == 1 else 0)

                    # Update remainder
                    new_remainder = (remainder * 10 + digit) % k

                    ans += dp(pos + 1, new_tight, new_even_count, new_odd_count, new_remainder, True)

                memo[key] = ans
                return ans

            return dp(0, True, 0, 0, 0, False)

        return count_beautiful_up_to(high) - count_beautiful_up_to(low - 1)
