import sys

def solve(grid, tiles_mask, H, W, tiles, remaining_area):
    # Base case: If all cells are covered
    if remaining_area == 0:
        return True

    # Find the first empty cell (row-by-row, then column-by-column)
    # We start search from the top-leftmost empty cell. This ensures
    # we don't explore the same tiling in different positions relative
    # to the empty space.
    row, col = -1, -1
    for r in range(H):
        for c in range(W):
            if grid[r][c] == 0:
                row, col = r, c
                break
        if row != -1:
            break

    # Optimization: Calculate sum of available tile areas
    # Check if the total area of unused tiles is enough to cover the remaining empty cells.
    available_tiles_area_sum = 0
    for i in range(len(tiles)):
        if (tiles_mask >> i) & 1:
            available_tiles_area_sum += tiles[i][0] * tiles[i][1]

    # Pruning: If total available area is less than the area needed, this path fails.
    if available_tiles_area_sum < remaining_area:
        return False

    # Try placing each available tile at the first empty cell (row, col)
    # Iterate through tiles by index
    for i in range(len(tiles)):
        # Check if tile i is available (i-th bit is set in tiles_mask)
        if (tiles_mask >> i) & 1:
            tile_dims = tiles[i] # (A_i, B_i)

            # Try original orientation (A_i x B_i)
            h1, w1 = tile_dims[0], tile_dims[1]

            # Check if tile fits within grid bounds starting at (row, col)
            # and if all target cells are currently empty
            if row + h1 <= H and col + w1 <= W:
                can_place1 = True
                for r_place in range(row, row + h1):
                    for c_place in range(col, col + w1):
                        if grid[r_place][c_place] == 1: # Check if cell is already covered
                            can_place1 = False
                            break
                    if not can_place1:
                        break

                if can_place1:
                    # Place the tile (mark cells as covered)
                    for r_place in range(row, row + h1):
                        for c_place in range(col, col + w1):
                            grid[r_place][c_place] = 1 # Mark cell as covered

                    # Recurse with the tile used and updated remaining area
                    # If the recursive call finds a solution, we're done
                    if solve(grid, tiles_mask ^ (1 << i), H, W, tiles, remaining_area - h1 * w1):
                        return True

                    # Backtrack: Unplace the tile (restore cells to empty)
                    # This is crucial for exploring other possibilities from the current state.
                    for r_place in range(row, row + h1):
                        for c_place in range(col, col + w1):
                            grid[r_place][c_place] = 0 # Restore cell to empty

            # Try rotated orientation (B_i x A_i), only if dimensions are different
            # Avoid redundant checks if A_i == B_i (square tile)
            if tile_dims[0] != tile_dims[1]:
                h2, w2 = tile_dims[1], tile_dims[0] # Rotated dimensions

                # Check if rotated tile fits within grid bounds starting at (row, col)
                # and if all target cells are currently empty
