    def minimumCost(self, m: int, n: int, horizontalCut: List[int], verticalCut: List[int]) -> int:
        # Create a memoization dictionary
        memo = {}

        # Helper function to calculate minimum cost using dynamic programming
        def dp(i, j, k, l):
            # Base case: if the cake is already 1x1
            if k - i == 1 and l - j == 1:
                return 0

            # Check if we've already computed this state
            if (i, j, k, l) in memo:
                return memo[(i, j, k, l)]

            result = float('inf')

            # Try all possible horizontal cuts
            for r in range(i, k - 1):
                cost = horizontalCut[r] + dp(i, j, r + 1, l) + dp(r + 1, j, k, l)
                result = min(result, cost)

            # Try all possible vertical cuts
            for c in range(j, l - 1):
                cost = verticalCut[c] + dp(i, j, k, c + 1) + dp(i, c + 1, k, l)
                result = min(result, cost)

            # Memoize the result
            memo[(i, j, k, l)] = result
            return result

        # Start the recursion for the entire cake
        return dp(0, 0, m, n)
