This is a classic backtracking problem. I'll use the optimization of always trying to fill the first empty cell, which significantly reduces the search space.

My approach:
1. Find the first empty cell in the grid (scanning left-to-right, top-to-bottom)
2. Try placing each unused tile at that position 
3. For each tile, try both orientations (unless it's square)
4. Use backtracking to explore all possibilities

```python
def find_first_empty(grid, h, w):
    for i in range(h):
        for j in range(w):
            if grid[i][j] == 0:
                return i, j
    return None, None

def can_place_tile(grid, h, w, tile_h, tile_w, row, col):
    if row + tile_h > h or col + tile_w > w:
        return False
    for i in range(row, row + tile_h):
        for j in range(col, col + tile_w):
            if grid[i][j] != 0:
                return False
    return True

def place_tile(grid, tile_h, tile_w, row, col, tile_id):
    for i in range(row, row + tile_h):
        for j in range(col, col + tile_w):
            grid[i][j] = tile_id

def remove_tile(grid, tile_h, tile_w, row, col):
    for i in range(row, row + tile_h):
        for j in range(col, col + tile_w):
            grid[i][j] = 0

def backtrack(grid, tiles, h, w, used):
    row, col = find_first_empty(grid, h, w)
    if row is None:  # Grid is completely filled
        return True

    for i in range(len(tiles)):
        if used[i]:
            continue

        a, b = tiles[i]
        orientations = [(a, b)] if a == b else [(a, b), (b, a)]

