class Solution:
    def minCostGoodCaption(self, caption: str) -> str:
        n = len(caption)
        if n < 3:
            return ""

        # dp[i] = minimum cost to make first i characters good
        dp = [float('inf')] * (n + 1)
        dp[0] = 0

        for i in range(3, n + 1):
            for j in range(0, i - 2):
                if dp[j] == float('inf'):
                    continue

                # Compute costs for all 26 characters efficiently
                costs = [0] * 26
                for k in range(j, i):
                    char_value = ord(caption[k]) - ord('a')
                    for c_idx in range(26):
                        costs[c_idx] += abs(char_value - c_idx)

                for c_idx in range(26):
                    dp[i] = min(dp[i], dp[j] + costs[c_idx])

        if dp[n] == float('inf'):
            return ""

        # Reconstruct the lexicographically smallest solution
        memo = {}

        def get_best_string(pos):
            if pos == 0:
                return ""

            if pos in memo:
                return memo[pos]

            best_result = None

            for j in range(0, pos - 2):
                if dp[j] == float('inf'):
                    continue

                # Compute costs for all 26 characters efficiently
                costs = [0] * 26
                for k in range(j, pos):
                    char_value = ord(caption[k]) - ord('a')
                    for c_idx in range(26):
                        costs[c_idx] += abs(char_value - c_idx)

                for c_idx in range(26):
                    if dp[j] + costs[c_idx] == dp[pos]:
                        c = chr(ord('a') + c_idx)
                        prefix = get_best_string(j)
                        current = c * (pos - j)
                        candidate = prefix + current

                        if best_result is None or candidate < best_result:
                            best_result = candidate

            memo[pos] = best_result
            return best_result

        return get_best_string(n)
