    graph.append(input().strip())

# Precompute edges by label for efficiency
out_edges = [defaultdict(list) for _ in range(n)]
in_edges = [defaultdict(list) for _ in range(n)]

for i in range(n):
    for j in range(n):
        if graph[i][j] != '-':
            label = graph[i][j]
            out_edges[i][label].append(j)
            in_edges[j][label].append(i)

def find_shortest_palindrome(start, end):
    # BFS by layers
    current_layer = {(start, end)}
    visited = {(start, end)}
    length = 0

    while current_layer:
        # Check for even-length palindromes in current layer
        for v1, v2 in current_layer:
            if v1 == v2:
                return length

        # Check for odd-length palindromes
        for v1, v2 in current_layer:
