from collections import deque

n = int(input())
graph = []
for i in range(n):
    graph.append(input().strip())

result = [[-1] * n for _ in range(n)]

for start_i in range(n):
    for start_j in range(n):
        # BFS to find shortest palindromic path from start_i to start_j
        visited = set()
        queue = deque()

        # Even length palindromes: start from single vertex
        for mid in range(n):
            queue.append((mid, mid, 0))
            visited.add((mid, mid))

        # Odd length palindromes: start from edge
        for u in range(n):
            for v in range(n):
                if graph[u][v] != '-' and (u, v) not in visited:
                    queue.append((u, v, 1))
                    visited.add((u, v))

        while queue:
            left, right, d = queue.popleft()

            if left == start_i and right == start_j:
                result[start_i][start_j] = d
                break

