class Solution:
    def maximumSubarraySum(self, nums: List[int], k: int) -> int:
        n = len(nums)
        max_sum = 0

        # Precompute prefix sums for efficient subarray sum calculation
        prefix_sum = [0] * (n + 1)
        for i in range(n):
            prefix_sum[i + 1] = prefix_sum[i] + nums[i]

        # Map: value -> list of indices where this value occurs
        value_indices = {}

        for j in range(n):
            current_value = nums[j]

            # Check for values that are k away
            for target_value in [current_value - k, current_value + k]:
                if target_value in value_indices:
                    for i in value_indices[target_value]:
                        # The sum of the subarray from i to j is prefix_sum[j+1] - prefix_sum[i]
                        subarray_sum = prefix_sum[j + 1] - prefix_sum[i]
                        max_sum = max(max_sum, subarray_sum)

            # Update the dictionary
            if current_value not in value_indices:
                value_indices[current_value] = []
            value_indices[current_value].append(j)

        return max_sum
