class Solution:
    def minimumCost(self, nums: List[int]) -> int:
        def is_palindrome(n):
            s = str(n)
            return s == s[::-1]

        candidates = set()

        # Add small palindromes
        for i in range(1, 1000):
            if is_palindrome(i):
                candidates.add(i)

        # Add palindromes around key values
        nums_sorted = sorted(nums)
        key_values = [nums_sorted[0], nums_sorted[-1], nums_sorted[len(nums_sorted) // 2]]

        for key_value in key_values:
            start = max(1, key_value - 2000)
            end = min(10**9, key_value + 2001)
            for candidate in range(start, end):
                if is_palindrome(candidate):
                    candidates.add(candidate)

        min_cost = float('inf')
        for p in candidates:
            cost = sum(abs(num - p) for num in nums)
            min_cost = min(min_cost, cost)

