class Solution:
    def lexicographicallySmallestArray(self, nums: List[int], limit: int) -> List[int]:
        n = len(nums)

        # Create a list of (value, index) pairs
        indexed_nums = [(num, i) for i, num in enumerate(nums)]

        # Sort by value
        indexed_nums.sort()

        # Create a Union-Find data structure
        parent = list(range(n))

        def find(x):
            if parent[x] != x:
                parent[x] = find(parent[x])
            return parent[x]

        def union(x, y):
            parent[find(x)] = find(y)

        # Union elements if they can be swapped
        for i in range(1, n):
            prev_val, prev_idx = indexed_nums[i-1]
            curr_val, curr_idx = indexed_nums[i]

            if curr_val - prev_val <= limit:
                union(prev_idx, curr_idx)

        # Group elements by their parent
        groups = {}
        for val, idx in indexed_nums:
            root = find(idx)
            if root not in groups:
                groups[root] = []
            groups[root].append((val, idx))

        # Reassign elements
        result = [0] * n
        for group in groups.values():
            values = [val for val, _ in group]
            indices = [idx for _, idx in group]

            # Sort indices
            indices.sort()

            for i, idx in enumerate(indices):
                result[idx] = values[i]

        return result
```

