```python
class Solution:
    def beautifulSplits(self, nums: List[int]) -> int:
        n = len(nums)

        # Precompute LCP array using DP
        # lcp[i][j] = length of longest common prefix of nums[i:] and nums[j:]
        lcp = [[0] * (n + 1) for _ in range(n + 1)]

        for i in range(n - 1, -1, -1):
            for j in range(n - 1, -1, -1):
                if i == j:
                    lcp[i][j] = n - i
                elif nums[i] == nums[j]:
                    lcp[i][j] = 1 + lcp[i + 1][j + 1]
                else:
                    lcp[i][j] = 0

        count = 0

        # Try all possible splits
        for i in range(1, n):
            for j in range(i + 1, n):
                # Check if nums1 is a prefix of nums2
                # nums1 = nums[0:i], nums2 = nums[i:j]
                is_prefix1 = lcp[0][i] >= i

                # Check if nums2 is a prefix of nums3
                # nums2 = nums[i:j], nums3 = nums[j:]
                is_prefix2 = lcp[i][j] >= j - i

                if is_prefix1 or is_prefix2:
                    count += 1

        return count
