    coordinates[1] = (0, 0)  # Person 1 is at origin

    known = {1}

    while True:
        newly_discovered = set()

        for A, B, X, Y in information:
            if A in known and B not in known:
                x_A, y_A = coordinates[A]
                coordinates[B] = (x_A + X, y_A + Y)
                newly_discovered.add(B)
            elif B in known and A not in known:
                x_B, y_B = coordinates[B]
                coordinates[A] = (x_B - X, y_B - Y)
                newly_discovered.add(A)

        if not newly_discovered:
            break

        known.update(newly_discovered)

    result = []
    for i in range(1, N + 1):
        if i not in known:
            result.append("undecidable")
        else:
            x, y = coordinates[i]
            result.append(f"{x} {y}")

    return result

