Looking at this problem, I need to count n-digit integers whose digits can be rearranged to form a palindrome that is divisible by k.

My approach:
1. Generate all possible digit frequency distributions for n digits
2. For each distribution, check if it can form a palindrome (at most one digit can have odd frequency)
3. If it can form a palindrome, check if any palindrome arrangement is divisible by k and doesn't start with 0
4. If valid, count how many n-digit numbers have this exact frequency distribution (excluding those starting with 0)

```python
from math import factorial

class Solution:
    def countGoodIntegers(self, n: int, k: int) -> int:
        def can_form_palindrome(freq):
            odd_count = sum(1 for f in freq if f % 2 == 1)
            return odd_count <= 1

        def has_valid_palindrome(freq):
            def backtrack(pos, current, remaining_freq):
                if pos == (n + 1) // 2:
                    # Construct full palindrome
                    if n % 2 == 1:
                        palindrome = current + current[-2::-1]
                    else:
                        palindrome = current + current[::-1]

                    if palindrome[0] != 0:
                        num = int(''.join(map(str, palindrome)))
                        if num % k == 0:
                            return True
                    return False

                for digit in range(10):
                    if pos == n // 2 and n % 2 == 1:
                        # Middle position for odd length
                        if remaining_freq[digit] >= 1:
                            remaining_freq[digit] -= 1
                            if backtrack(pos + 1, current + [digit], remaining_freq):
                                remaining_freq[digit] += 1
                                return True
                            remaining_freq[digit] += 1
                    else:
                        # Regular position (need pairs)
                        if remaining_freq[digit] >= 2:
                            remaining_freq[digit] -= 2
                            if backtrack(pos + 1, current + [digit], remaining_freq):
                                remaining_freq[digit] += 2
                                return True
                            remaining_freq[digit] += 2

                return False

            return backtrack(0, [], freq[:])

        def count_permutations(freq):
            # Calculate total permutations
            total = factorial(n)
            for f in freq:
                total //= factorial(f)

            # Subtract permutations starting with 0
            if freq[0] > 0:
                freq[0] -= 1
                invalid = factorial(n - 1)
                for f in freq:
                    invalid //= factorial(f)
                freq[0] += 1
                return total - invalid

            return total

        result = 0

        def generate_all_frequencies(remaining_digits, digit_index, current_freq):
            nonlocal result

            if remaining_digits == 0:
                if can_form_palindrome(current_freq):
                    if has_valid_palindrome(current_freq):
                        result += count_permutations(current_freq)
                return

            if digit_index == 10:
                return

            # Try all possible counts for current digit
            for count in range(remaining_digits + 1):
                current_freq[digit_index] = count
                generate_all_frequencies(remaining_digits - count, digit_index + 1, current_freq)

        generate_all_frequencies(n, 0, [0] * 10)
        return result
