class Solution:
    def minOperations(self, nums: List[int]) -> int:
        n = len(nums)
        if n == 1:
            return 0

        operations = 0
        processed_nums = nums.copy()  # Create a copy to avoid modifying the original array

        # Process the array from right to left
        for i in range(n - 2, -1, -1):
            if processed_nums[i] > processed_nums[i + 1]:
                ops_for_current = 0
                current = processed_nums[i]

                # Keep dividing by greatest proper divisor until current <= next element
                while current > processed_nums[i + 1]:
                    next_value = self.divide_by_gpd(current)
                    if next_value == current:
                        # Current is a prime and cannot be reduced further
                        return -1
                    current = next_value
                    ops_for_current += 1

                operations += ops_for_current
                processed_nums[i] = current

        return operations

    def divide_by_gpd(self, n):
        """Divides n by its greatest proper divisor."""
        if n == 1:
            return 1

        # Find the smallest prime factor
        for i in range(2, int(n**0.5) + 1):
            if n % i == 0:
                return i

        # If n is prime, the result is n
        return n
