class Solution:
    def minOperations(self, nums: List[int]) -> int:
        def find_gpd(n):
            if n == 1:
                return 1

            for d in range(n // 2, 0, -1):
                if n % d == 0:
                    return d

            return 1  # This should never be reached for n > 1

        def can_reduce_to_target(n, target):
            if n <= target:
                return 0

            queue = [(n, 0)]  # (Value, operations count)
            visited = {n}

            while queue:
                current, ops = queue.pop(0)

                if current <= target:
                    return ops

                gpd = find_gpd(current)
                next_value = current // gpd

                if next_value not in visited:
                    visited.add(next_value)
                    queue.append((next_value, ops + 1))

            return -1

        total_operations = 0

        for i in range(len(nums) - 1):
            if nums[i] > nums[i+1]:
                operations = can_reduce_to_target(nums[i], nums[i+1])
                if operations == -1:
                    return -1
                total_operations += operations

        return total_operations
