Looking at this problem, I need to find the maximum sum of non-adjacent subsequence after each update query.

This is a classic dynamic programming problem (house robber), but doing it naively for each query would be O(n*q) which might be too slow.

I'll use a segment tree where each node stores a 2x2 matrix representing:
- [0][0]: max sum when leftmost element is NOT taken and rightmost element is NOT taken
- [0][1]: max sum when leftmost element is NOT taken and rightmost element IS taken  
- [1][0]: max sum when leftmost element IS taken and rightmost element is NOT taken
- [1][1]: max sum when leftmost element IS taken and rightmost element IS taken

When merging two segments, I need to ensure adjacent elements aren't both selected.

```python
class Solution:
    def maximumSumSubsequence(self, nums: List[int], queries: List[List[int]]) -> int:
        class SegmentTree:
            def __init__(self, nums):
                self.n = len(nums)
                self.tree = [[[float('-inf'), float('-inf')], [float('-inf'), float('-inf')]] for _ in range(4 * self.n)]
                self.build(nums, 0, 0, self.n - 1)

            def build(self, nums, node, start, end):
                if start == end:
                    self.tree[node][0][0] = 0
                    self.tree[node][1][1] = nums[start]
                else:
                    mid = (start + end) // 2
                    left_child = 2 * node + 1
                    right_child = 2 * node + 2
                    self.build(nums, left_child, start, mid)
                    self.build(nums, right_child, mid + 1, end)
                    self.merge(node, left_child, right_child)

            def merge(self, node, left, right):
                for a in range(2):
                    for b in range(2):
                        self.tree[node][a][b] = max(
                            self.tree[left][a][0] + self.tree[right][0][b],
                            self.tree[left][a][0] + self.tree[right][1][b],
                            self.tree[left][a][1] + self.tree[right][0][b]
                        )

            def update(self, node, start, end, idx, val):
                if start == end:
                    self.tree[node][0][0] = 0
                    self.tree[node][1][1] = val
                else:
                    mid = (start + end) // 2
                    left_child = 2 * node + 1
                    right_child = 2 * node + 2
                    if idx <= mid:
                        self.update(left_child, start, mid, idx, val)
                    else:
                        self.update(right_child, mid + 1, end, idx, val)
                    self.merge(node, left_child, right_child)

            def query(self):
                return max(0, self.tree[0][0][0], self.tree[0][0][1], self.tree[0][1][0], self.tree[0][1][1])

        MOD = 10**9 + 7
        st = SegmentTree(nums)
        total = 0

        for pos, x in queries:
            st.update(0, 0, len(nums) - 1, pos, x)
            total = (total + st.query()) % MOD

        return total
