class Solution:
    def sumOfGoodSubsequences(self, nums: List[int]) -> int:
        MOD = 10**9 + 7

        # ways[v] = number of ways to end a subsequence with value v
        # sums[v] = sum of all elements in subsequences ending with value v
        ways = {}
        sums = {}

        for val in nums:
            new_ways = 1  # Start a new subsequence with just val
            new_sums = val  # Sum of the new subsequence

            # Ways to add val to an existing subsequence
            for prev_val in [val-1, val+1]:
                if prev_val in ways:
                    new_ways = (new_ways + ways[prev_val]) % MOD
                    new_sums = (new_sums + sums[prev_val] + ways[prev_val] * val) % MOD

            if val not in ways:
                ways[val] = 0
                sums[val] = 0
            ways[val] = (ways[val] + new_ways) % MOD
            sums[val] = (sums[val] + new_sums) % MOD

        # Sum up all subsequences
        total_sum = 0
        for val, s in sums.items():
            total_sum = (total_sum + s) % MOD

        return total_sum
