Since I'm restricted to palindromic numbers, I need to find palindromic numbers close to the median and check which gives the minimum cost.

```python
class Solution:
    def minimumCost(self, nums: List[int]) -> int:
        def is_palindrome(n):
            s = str(n)
            return s == s[::-1]

        n = len(nums)
        sorted_nums = sorted(nums)

        # Find median
        if n % 2 == 1:
            median = sorted_nums[n // 2]
        else:
            median = (sorted_nums[n // 2 - 1] + sorted_nums[n // 2]) // 2

        # Find palindromic candidates around the median
        candidates = []

        # Search for palindromes starting from median and going outward
        max_dist = min(median - 1, 10**9 - median - 1, 10**6)

        for dist in range(max_dist + 1):
            # Check at median - dist
            if median - dist >= 1:
                if is_palindrome(median - dist):
                    candidates.append(median - dist)

            # Check at median + dist (skip dist=0 to avoid duplicate)
            if dist > 0 and median + dist < 10**9:
                if is_palindrome(median + dist):
                    candidates.append(median + dist)

            # Stop early if we have found palindromes on both sides
            if len(candidates) >= 2:
                has_left = any(c < median for c in candidates)
                has_right = any(c >= median for c in candidates)
                if has_left and has_right:
                    break

        # Calculate minimum cost
        min_cost = float('inf')
        for candidate in candidates:
            cost = sum(abs(x - candidate) for x in nums)
            min_cost = min(min_cost, cost)

        return min_cost
