def num_sq_sum(s, N):
    """Counts squares (i, j) with i+j = s within 1 <= i, j <= N."""
    if s < 2 or s > 2 * N:
        return 0
    # Number of pairs (i, j) with i+j = s where i, j >= 1 is s-1.
    # We also need i <= N and j <= N.
    # i <= N => s-j <= N => s-N <= j
    # j <= N => s-i <= N => s-N <= i
    # i must be in [max(1, s-N), min(N, s-1)]
    # Number of integers = min(N, s-1) - max(1, s-N) + 1
    # This simplifies to min(s - 1, 2 * N + 1 - s) for 2 <= s <= 2 * N.
    return min(s - 1, 2 * N + 1 - s)

