            # Base case: if we have used all 0s and 1s
            if zeros_left == 0 and ones_left == 0:
                return 1

            # Check memoization table
            if (zeros_left, ones_left, last_digit, run_length) in memo:
                return memo[(zeros_left, ones_left, last_digit, run_length)]

            total = 0

            # Try adding a 0
            if zeros_left > 0:
                if last_digit == 0:
                    # Adding a 0 after a 0, check if run_length is within limits
                    if run_length < limit:
                        total = (total + count_arrays(zeros_left - 1, ones_left, 0, run_length + 1)) % MOD
                else:  # last_digit == 1
                    # Adding a 0 after a 1, start a new run
                    total = (total + count_arrays(zeros_left - 1, ones_left, 0, 1)) % MOD

            # Try adding a 1
            if ones_left > 0:
                if last_digit == 1:
                    # Adding a 1 after a 1, check if run_length is within limits
                    if run_length < limit:
                        total = (total + count_arrays(zeros_left, ones_left - 1, 1, run_length + 1)) % MOD
                else:  # last_digit == 0
                    # Adding a 1 after a 0, start a new run
                    total = (total + count_arrays(zeros_left, ones_left - 1, 1, 1)) % MOD

            memo[(zeros_left, ones_left, last_digit, run_length)] = total
            return total

        # We need to handle the first element specially, as there's no previous digit
        # We can start with either a 0 or a 1
        total = 0

