            for i, (_, dest) in enumerate(outgoing_edges[node]):
                if i < threshold:
                    adj_list[node].append(dest)

        # Check if all nodes can reach node 0 using BFS from node 0 in the reverse graph
        reverse_adj_list = [[] for _ in range(n)]
        for node in range(n):
            for neighbor in adj_list[node]:
                reverse_adj_list[neighbor].append(node)

        visited = [False] * n
        queue = deque([0])
        visited[0] = True

        while queue:
            node = queue.popleft()

            for neighbor in reverse_adj_list[node]:
                if not visited[neighbor]:
                    visited[neighbor] = True
                    queue.append(neighbor)

