    def minArraySum(self, nums: List[int], k: int, op1: int, op2: int) -> int:
        n = len(nums)

        @lru_cache(None)
        def dp(i, o1, o2):
            if i == n:
                return 0

            # Don't apply any operation
            result = nums[i] + dp(i + 1, o1, o2)

            # Apply Operation 1
            if o1 > 0:
                result = min(result, math.ceil(nums[i] / 2) + dp(i + 1, o1 - 1, o2))

            # Apply Operation 2
            if o2 > 0 and nums[i] >= k:
                result = min(result, nums[i] - k + dp(i + 1, o1, o2 - 1))

            # Apply both Operations 1 and 2
            if o1 > 0 and o2 > 0 and nums[i] >= k:
                # Apply Operation 2 then Operation 1
                op2_then_op1 = math.ceil((nums[i] - k) / 2)

                # Apply Operation 1 then Operation 2
                op1_then_op2 = math.ceil(nums[i] / 2)
                if op1_then_op2 >= k:
                    op1_then_op2 -= k

                result = min(result, min(op1_then_op2, op2_then_op1) + dp(i + 1, o1 - 1, o2 - 1))

            return result

        return dp(0, op1, op2)
