                    if abs(nums[i] - nums[i+1]) > max_diff:
                        return False

            # DP to check if we can assign x or y to each -1
            # dp[i][j] = can we process first i+1 elements where:
            # j = 0: element i gets its original value (if not -1) or x (if -1)
            # j = 1: element i gets y (only valid if element i is -1)

            dp = [[False, False] for _ in range(n)]

            # Base case
            if nums[0] == -1:
                dp[0][0] = True  # Use x
                dp[0][1] = True  # Use y
            else:
                dp[0][0] = True  # Use original value
                dp[0][1] = False

            # Fill DP
            for i in range(1, n):
                if nums[i] == -1:
                    # Can use either x or y

                    # Try using x at position i
                    if dp[i-1][0]:
                        prev_val = nums[i-1] if nums[i-1] != -1 else x
                        if abs(prev_val - x) <= max_diff:
                            dp[i][0] = True

                    if dp[i-1][1]:
                        prev_val = y
                        if abs(prev_val - x) <= max_diff:
