                    if dp[i-1][0]:
                        prev_val = nums[i-1] if nums[i-1] != -1 else x
                        if abs(prev_val - y) <= max_diff:
                            dp[i][1] = True

                    if dp[i-1][1]:
                        prev_val = y
                        if abs(prev_val - y) <= max_diff:
                            dp[i][1] = True
                else:
                    # Must use original value
                    curr_val = nums[i]

                    if dp[i-1][0]:
                        prev_val = nums[i-1] if nums[i-1] != -1 else x
                        if abs(prev_val - curr_val) <= max_diff:
                            dp[i][0] = True

                    if dp[i-1][1]:
                        prev_val = y
                        if abs(prev_val - curr_val) <= max_diff:
                            dp[i][0] = True

                    dp[i][1] = False

            return dp[n-1][0] or dp[n-1][1]

        def can_achieve(max_diff):
            # Generate candidates for x and y
            candidates = set()

            # Add existing values
            for val in nums:
