class Solution:
    def earliestSecondToMarkIndices(self, nums: List[int], changeIndices: List[int]) -> int:
        n, m = len(nums), len(changeIndices)

        def can_mark_all_indices_by_time(time):
            # Convert to 0-indexed for convenience
            change_indices = [idx - 1 for idx in changeIndices[:time]]

            # Collect all occurrences of each index in change_indices
            occurrences = {}
            for s in range(time):
                idx = change_indices[s]
                occurrences.setdefault(idx, []).append(s)

            # Check if all indices appear in change_indices
            if len(occurrences) < n:
                return False

            # For each index, use the last occurrence as the mark time
            mark_times = {}
            for idx, occs in occurrences.items():
                mark_times[idx] = occs[-1]

            # Sort indices based on (earliest mark time)
            indices_sorted = sorted(range(n), key=lambda idx: mark_times.get(idx, time) if idx in mark_times else time)

            # Simulate the operations
            seconds_used = [False] * time

            # For each index, allocate seconds for marking and decrements
            for idx in indices_sorted:
                if idx not in mark_times:
                    return False

                # Mark this index at its mark time
                mark_time = mark_times[idx]
                seconds_used[mark_time] = True

                # Try to allocate seconds for decrements
                decrements = nums[idx]
                for s in range(mark_time):
                    if not seconds_used[s]:
                        seconds_used[s] = True
                        decrements -= 1
                        if decrements == 0:
                            break

                if decrements > 0:
                    return False

            return True

        left, right = 1, m + 1
        while left < right:
            mid = (left + right) // 2
            if can_mark_all_indices_by_time(mid):
                right = mid
            else:
                left = mid + 1

        return left if left <= m else -1
