import heapq

class Solution:
    def minOperations(self, n: int, m: int) -> int:
        # Helper function to check if a number is prime
        def is_prime(num):
            if num < 2:
                return False
            if num == 2:
                return True
            if num % 2 == 0:
                return False
            for i in range(3, int(num**0.5) + 1, 2):
                if num % i == 0:
                    return False
            return True

        # If n or m is prime, return -1
        if is_prime(n) or is_prime(m):
            return -1

        # If n == m, return n
        if n == m:
            return n

        # Get number of digits
        digits = len(str(n))
        min_val = 10**(digits-1) if digits > 1 else 1
        max_val = 10**digits - 1

        # Generate all possible next states from current state
        def get_next_states(current):
            current_str = str(current).zfill(digits)
            next_states = []

            for i in range(digits):
                digit = int(current_str[i])

                # Increase digit by 1 (if not 9)
                if digit < 9:
                    new_str = current_str[:i] + str(digit + 1) + current_str[i+1:]
                    new_num = int(new_str)
                    if min_val <= new_num <= max_val and not is_prime(new_num):
                        next_states.append(new_num)

                # Decrease digit by 1 (if not 0)
                if digit > 0:
                    new_str = current_str[:i] + str(digit - 1) + current_str[i+1:]
                    new_num = int(new_str)
                    if min_val <= new_num <= max_val and not is_prime(new_num):
                        next_states.append(new_num)

            return next_states

        # Dijkstra's algorithm
        pq = [(n, n)]  # (cost, current_number)
        visited = set()

        while pq:
            cost, current = heapq.heappop(pq)

            if current in visited:
                continue

            visited.add(current)

            if current == m:
                return cost

            for next_num in get_next_states(current):
                if next_num not in visited:
                    heapq.heappush(pq, (cost + next_num, next_num))

        return -1
```

