Looking at this problem, I need to track all possible sequences of operations and count how many lead to valid results.

Let me break down the problem:
1. We have a sequence S of length N, initially all zeros
2. For each operation i, we can choose between two options:
   - Replace S[1] to S[P_i] with V_i (if all current values ≤ V_i)
   - Replace S[P_i] to S[N] with V_i (if all current values ≤ V_i)
3. Count valid sequences of choices

I'll use dynamic programming with memoization, representing the sequence state as segments with constant values.

Key insights:
- After each operation, the sequence consists of segments with constant values
- I only need to track the segment boundaries and values
- Use memoization to avoid recomputing the same states

```python
N, Q = map(int, input().split())
operations = []
for _ in range(Q):
    P, V = map(int, input().split())
    operations.append((P-1, V))  # Convert to 0-indexed

MOD = 998244353

memo = {}

def dfs(op_idx, segments):
    if op_idx == Q:
        return 1

    key = (op_idx, segments)
    if key in memo:
        return memo[key]

    P, V = operations[op_idx]
    count = 0

    # Choice 1: Replace S[0], ..., S[P] with V
    max_val_in_range = 0
    for start, end, val in segments:
        if start <= P:
            max_val_in_range = max(max_val_in_range, val)

    if max_val_in_range <= V:
        new_segments = []
        if P >= 0:
            new_segments.append((0, P+1, V))
        for start, end, val in segments:
            if start > P:
                new_segments.append((start, end, val))
            elif end > P+1:
                new_segments.append((P+1, end, val))

        # Normalize new_segments
        new_segments = [seg for seg in new_segments if seg[0] < seg[1]]
        new_segments.sort()
        normalized = []
        for start, end, val in new_segments:
            if normalized and normalized[-1][1] == start and normalized[-1][2] == val:
                normalized[-1] = (normalized[-1][0], end, val)
            else:
                normalized.append((start, end, val))

        count += dfs(op_idx + 1, tuple(normalized))
        count %= MOD

    # Choice 2: Replace S[P], ..., S[N-1] with V
    max_val_in_range = 0
    for start, end, val in segments:
        if end > P:
            max_val_in_range = max(max_val_in_range, val)

    if max_val_in_range <= V:
        new_segments = []
        for start, end, val in segments:
            if end <= P:
                new_segments.append((start, end, val))
            elif start < P:
                new_segments.append((start, P, val))
        if P < N:
            new_segments.append((P, N, V))

        # Normalize new_segments
        new_segments = [seg for seg in new_segments if seg[0] < seg[1]]
        new_segments.sort()
        normalized = []
        for start, end, val in new_segments:
            if normalized and normalized[-1][1] == start and normalized[-1][2] == val:
                normalized[-1] = (normalized[-1][0], end, val)
            else:
                normalized.append((start, end, val))

        count += dfs(op_idx + 1, tuple(normalized))
        count %= MOD

    memo[key] = count
    return count

