Looking at this problem, I need to find the maximum size subgraph that forms an alkane - a tree where every vertex has degree 1 or 4, with at least one vertex of degree 4.

From the handshaking lemma, if there are x vertices of degree 1 and y vertices of degree 4, then:
- x + 4y = 2(x + y - 1) (sum of degrees = 2 × edges)
- This gives us x = 2y + 2

So valid alkane sizes are 3y + 2 where y ≥ 1, giving sizes 5, 8, 11, 14, ...

I'll use tree DP rooted at different vertices to find the maximum alkane subgraph.

```python
def solve():
    n = int(input())
    adj = [[] for _ in range(n + 1)]
    for _ in range(n - 1):
        a, b = map(int, input().split())
        adj[a].append(b)
        adj[b].append(a)

    best_global = -1

    # Try different roots
    for root in range(1, min(n + 1, 10)):
        # Build rooted tree
        children = [[] for _ in range(n + 1)]
        visited = [False] * (n + 1)

        def dfs(v, p):
            visited[v] = True
            for u in adj[v]:
                if u != p and not visited[u]:
                    children[v].append(u)
                    dfs(u, v)

        dfs(root, -1)

        # DP: dp[v][k][has_deg4] = max size where v connects to k children
        memo = {}

        def dp(v, k, has_deg4):
            if (v, k, has_deg4) in memo:
                return memo[(v, k, has_deg4)]

            if k > len(children[v]) or k < 0:
                result = -1
            else:
                if k == 0:
                    result = 1
                else:
                    # Choose best k children to connect to
                    child_values = []

                    for c in children[v]:
                        best_connect = -1
                        # Try different degrees for child c
                        for kc in range(len(children[c]) + 1):
                            for child_has_deg4 in [False, True]:
                                val = dp(c, kc, child_has_deg4)
                                if val > 0:
                                    c_degree = kc + 1  # +1 for connection to v
                                    if c_degree in [1, 4]:
                                        child_deg4 = child_has_deg4 or (c_degree == 4)
                                        best_connect = max(best_connect, val)

                        best_no_connect = 0
                        for kc in range(len(children[c]) + 1):
                            val = dp(c, kc, True)  # Child subtree must have deg4
                            if val > 0:
                                if kc in [1, 4]:
                                    best_no_connect = max(best_no_connect, val)

                        child_values.append((best_connect, best_no_connect))

                    # Select k best children to connect
                    benefits = []
                    base_sum = 0
                    valid = True

                    for i, (connect, no_connect) in enumerate(child_values):
                        base_sum += no_connect
                        if connect >= 0:
                            benefits.append((connect - no_connect, i))
                        else:
                            benefits.append((-float('inf'), i))

                    benefits.sort(reverse=True)

                    if len([b for b, _ in benefits if b != -float('inf')]) >= k:
                        result = 1 + base_sum + sum(b for b, _ in benefits[:k])
                    else:
                        result = -1

            memo[(v, k, has_deg4)] = result
            return result

        # Try root with degree 1 or 4
        for root_deg in [1, 4]:
            val = dp(root, root_deg, root_deg == 4)
            if val >= 5:  # Valid alkane size
                best_global = max(best_global, val)

    return best_global if best_global >= 5 else -1

