Looking at this problem, I need to find the minimum absolute difference between two elements that are at least x indices apart.

My approach:
1. For each index i, I need to consider all elements that are at least x positions away (either to the left or right)
2. I'll use a sorted list to efficiently find the closest value to nums[i]
3. I'll make two passes - one checking elements to the left, another checking elements to the right

Here's my solution:

```python
import bisect

class Solution:
    def minAbsoluteDifference(self, nums: List[int], x: int) -> int:
        n = len(nums)
        min_diff = float('inf')

        # Check elements on the left
        sorted_list = []
        for i in range(n):
            if i >= x:
                bisect.insort(sorted_list, nums[i - x])

            if sorted_list:
                pos = bisect.bisect_left(sorted_list, nums[i])
                if pos < len(sorted_list):
                    min_diff = min(min_diff, abs(nums[i] - sorted_list[pos]))
                if pos > 0:
                    min_diff = min(min_diff, abs(nums[i] - sorted_list[pos - 1]))

        # Check elements on the right
        sorted_list = []
        for i in range(n - 1, -1, -1):
            if i + x < n:
                bisect.insort(sorted_list, nums[i + x])

            if sorted_list:
                pos = bisect.bisect_left(sorted_list, nums[i])
                if pos < len(sorted_list):
                    min_diff = min(min_diff, abs(nums[i] - sorted_list[pos]))
                if pos > 0:
                    min_diff = min(min_diff, abs(nums[i] - sorted_list[pos - 1]))

        return min_diff
```

