Looking at this problem, I need to:

1. Understand what values each number can become through operations
2. Find the minimum operations to make the array non-decreasing

Let me analyze what happens when we divide by the greatest proper divisor:
- For a composite number n with smallest prime factor p, the greatest proper divisor is n/p
- For a prime number, the greatest proper divisor is 1, so dividing by 1 doesn't change it

This means each number can be reduced to a sequence of values until it reaches either 1 or its smallest prime factor.

I'll use dynamic programming where `dp[i][value]` represents the minimum operations to make the first i elements non-decreasing with the i-th element having the given value.

```python
class Solution:
    def minOperations(self, nums: List[int]) -> int:
        def get_greatest_proper_divisor(num):
            if num <= 1:
                return None
            # Find the smallest prime factor
            spf = num
            for i in range(2, int(num**0.5) + 1):
                if num % i == 0:
                    spf = i
                    break
            if spf == num:
                # num is prime, greatest proper divisor is 1
                return 1
            else:
                # greatest proper divisor is num // spf
                return num // spf

        def get_possible_values(n):
            values = []
            current = n
            operations = 0

            while True:
                values.append((current, operations))

                if current == 1:
                    break

                gpd = get_greatest_proper_divisor(current)
                if gpd is None or gpd == 1:
                    # current is prime or 1, cannot be reduced further
                    break

                current = current // gpd
                operations += 1

            return values

        n = len(nums)
        all_possible = [get_possible_values(num) for num in nums]

        # DP
        dp = [{}]

        # Initialize for the first element
        for value, ops in all_possible[0]:
            dp[0][value] = ops

        for i in range(1, n):
            dp.append({})
            for value, ops in all_possible[i]:
                min_prev_ops = float('inf')
                for prev_value in dp[i-1]:
                    if prev_value <= value:
                        min_prev_ops = min(min_prev_ops, dp[i-1][prev_value])
                if min_prev_ops != float('inf'):
                    dp[i][value] = min_prev_ops + ops

        if not dp[n-1]:
            return -1

        return min(dp[n-1].values())
```

