from collections import defaultdict
from itertools import combinations

def solve():
    N = int(input())

    # If N < 5, it's impossible to have an alkane (need at least one vertex of degree 4)
    if N < 5:
        return -1

    # Build the tree
    graph = defaultdict(list)
    for _ in range(N - 1):
        a, b = map(int, input().split())
        graph[a].append(b)
        graph[b].append(a)

    # Check if there's any vertex with degree at least 4
    if not any(len(graph[node]) >= 4 for node in graph):
        return -1

    # DP states: dp[node][parent_link][deg][has_deg4]
    # parent_link: 0 = not connected to parent, 1 = connected to parent
    # deg: 0 = not in alkane, 1 = leaf in alkane, 4 = internal node in alkane
    # has_deg4: 0 = subtree has no degree-4 vertex, 1 = subtree has at least one degree-4 vertex
    dp = {}

    def dfs(node, parent):
        # Initialize states
        for pl in [0, 1]:
            for d in [0, 1, 4]:
                for h in [0, 1]:
                    dp[(node, pl, d, h)] = -float('inf')

        # Base cases
        dp[(node, 0, 0, 0)] = 0  # Not in alkane
        dp[(node, 1, 0, 0)] = -float('inf')  # Invalid: connected to parent but not in alkane

        children = [c for c in graph[node] if c != parent]
        if not children:  # Leaf in the original tree
            dp[(node, 0, 1, 0)] = 1  # Leaf in alkane (not connected to parent)
            dp[(node, 1, 1, 0)] = 1  # Leaf in alkane (connected to parent)
            return

        # Process children recursively
        child_results = []
        for child in children:
            dfs(child, node)

            # Store results for this child
            child_result = [
                [dp[(child, 0, 0, 0)], dp[(child, 0, 0, 1)], dp[(child, 0, 1, 0)], dp[(child, 0, 1, 1)], dp[(child, 0, 4, 1)]],
                [dp[(child, 1, 0, 0)], dp[(child, 1, 0, 1)], dp[(child, 1, 1, 0)], dp[(child, 1, 1, 1)], dp[(child, 1, 4, 1)]],
            ]
            child_results.append(child_result)

        # Case: node not in alkane
        dp[(node, 0, 0, 0)] = 0
        dp[(node, 0, 0, 1)] = -float('inf')

        # For each child, take the best option where it's not connected to this node
        for child_result in child_results:
            best_child_not_connected = max(child_result[0])
            dp[(node, 0, 0, 0)] += max(0, best_child_not_connected)
            if best_child_not_connected > 0 and child_result[0].index(best_child_not_connected) % 2 == 1:
                dp[(node, 0, 0, 1)] = max(dp[(node, 0, 0, 1)], dp[(node, 0, 0, 0)])

        # Case: node is a leaf (degree 1) in alkane
        if len(children) >= 1:
            # Connected to one child only
            for i, child in enumerate(children):
                # Child is connected to this node
                for d_child in [1, 4]:
                    for h_child in [0, 1]:
                        if d_child == 4:
                            h_child = 1  # If child has degree 4, it definitely has a vertex of degree 4

                        child_val = dp[(child, 1, d_child, h_child)]
                        if child_val == -float('inf'):
                            continue

                        # Sum up values for all other children (not connected)
                        other_children_val = 0
                        other_has_deg4 = False
                        for j, other_child in enumerate(children):
                            if j == i:
                                continue
                            best_val = max(child_results[j][0])
                            if best_val > 0:
                                other_children_val += best_val
                                if child_results[j][0].index(best_val) % 2 == 1:
                                    other_has_deg4 = True

                        total_val = 1 + child_val + other_children_val
                        has_deg4 = h_child == 1 or other_has_deg4

                        dp[(node, 0, 1, int(has_deg4))] = max(dp[(node, 0, 1, int(has_deg4))], total_val)

        # Node is connected to parent and is a leaf
        dp[(node, 1, 1, 0)] = 1
        for child_result in child_results:
            best_child_not_connected = max(child_result[0])
            if best_child_not_connected > 0:
                dp[(node, 1, 1, 0)] += best_child_not_connected
                if child_result[0].index(best_child_not_connected) % 2 == 1:
                    dp[(node, 1, 1, 1)] = max(dp[(node, 1, 1, 1)], dp[(node, 1, 1, 0)])

        # Node is an internal node (degree 4)
        # Case 1: Not connected to parent, connected to 4 children
        if len(children) >= 4:
            for selected_indices in combinations(range(len(children)), 4):
                total_val = 1  # Count the node itself
                has_deg4 = True  # The node itself has degree 4

                # Process the selected children (connected to node)
                for i in selected_indices:
                    child = children[i]
                    best_val = max(dp[(child, 1, 1, 0)], dp[(child, 1, 1, 1)], dp[(child, 1, 4, 1)])
                    if best_val == -float('inf'):
                        total_val = -float('inf')
                        break
                    total_val += best_val

                if total_val == -float('inf'):
                    continue

                # Process the unselected children (not connected to node)
                for i in range(len(children)):
                    if i not in selected_indices:
                        best_val = max(child_results[i][0])
                        if best_val > 0:
                            total_val += best_val
                            if child_results[i][0].index(best_val) % 2 == 1:
                                has_deg4 = True

                dp[(node, 0, 4, 1)] = max(dp[(node, 0, 4, 1)], total_val)

        # Case 2: Connected to parent, connected to 3 children
        if len(children) >= 3:
            for selected_indices in combinations(range(len(children)), 3):
                total_val = 1  # Count the node itself
                has_deg4 = True  # The node itself has degree 4

                # Process the selected children (connected to node)
                for i in selected_indices:
                    child = children[i]
                    best_val = max(dp[(child, 1, 1, 0)], dp[(child, 1, 1, 1)], dp[(child, 1, 4, 1)])
                    if best_val == -float('inf'):
                        total_val = -float('inf')
                        break
                    total_val += best_val

                if total_val == -float('inf'):
                    continue

                # Process the unselected children (not connected to node)
                for i in range(len(children)):
                    if i not in selected_indices:
                        best_val = max(child_results[i][0])
                        if best_val > 0:
                            total_val += best_val
                            if child_results[i][0].index(best_val) % 2 == 1:
                                has_deg4 = True

                dp[(node, 1, 4, 1)] = max(dp[(node, 1, 4, 1)], total_val)

    # Find the root with maximum degree
    root = 1
    for node in graph:
        if len(graph[node]) > len(graph[root]):
