Looking at this problem, I need to count "Snake numbers" - numbers where the first digit is strictly larger than all other digits.

I'll use digit dynamic programming to efficiently count these numbers. The key insight is that once we place the first non-zero digit, all subsequent digits must be strictly smaller than it.

```python
# YOUR CODE HERE
def count_snake_numbers(n):
    if n < 10:
        return 0

    s = str(n)
    m = len(s)
    memo = {}

    def dp(pos, tight, started, first_digit):
        if pos == m:
            return 1 if started else 0

        state = (pos, tight, started, first_digit)
        if state in memo:
            return memo[state]

        limit = int(s[pos]) if tight else 9
        res = 0

        for digit in range(0, limit + 1):
            if not started:
                if digit == 0:
                    res += dp(pos + 1, tight and (digit == limit), False, -1)
                else:
                    res += dp(pos + 1, tight and (digit == limit), True, digit)
            else:
                if digit < first_digit:
                    res += dp(pos + 1, tight and (digit == limit), True, first_digit)

        memo[state] = res
        return res

    return dp(0, True, False, -1)

