```python
class Solution:
    def permute(self, n: int, k: int) -> List[int]:
        from functools import lru_cache

        @lru_cache(None)
        def count_perms(remaining, last_parity):
            if not remaining:
                return 1

            count = 0
            for num in remaining:
                if last_parity is None or (num % 2) != last_parity:
                    new_remaining = tuple(x for x in remaining if x != num)
                    count += count_perms(new_remaining, num % 2)

            return count

        def generate_kth(remaining, last_parity, target):
            if not remaining:
                return []

            cumulative = 0
            for num in sorted(remaining):
                if last_parity is None or (num % 2) != last_parity:
                    new_remaining = tuple(x for x in remaining if x != num)
                    count = count_perms(new_remaining, num % 2)
                    if cumulative + count >= target:
                        rest = generate_kth(new_remaining, num % 2, target - cumulative)
                        return [num] + rest
                    cumulative += count

            return []

        all_nums = tuple(range(1, n + 1))
        total = count_perms(all_nums, None)

        if k > total:
            return []

        return generate_kth(all_nums, None, k)
