class Solution:
    def canTraverseAllPairs(self, nums: List[int]) -> bool:
        n = len(nums)
        if n == 1:
            return True

        # Check if any number is 1
        if 1 in nums:
            return False

        # Union-Find
        parent = list(range(n))

        def find(x):
            if parent[x] != x:
                parent[x] = find(parent[x])
            return parent[x]

        def union(x, y):
            px, py = find(x), find(y)
            if px != py:
                parent[px] = py

        # Map prime factors to indices
        prime_to_indices = {}

        # Find prime factors for each number
        for i, num in enumerate(nums):
            # Find prime factors
            d = 2
            temp = num
            while d * d <= temp:
                if temp % d == 0:
                    if d not in prime_to_indices:
                        prime_to_indices[d] = []
                    prime_to_indices[d].append(i)
                    while temp % d == 0:
                        temp //= d
                d += 1
            if temp > 1:
                if temp not in prime_to_indices:
                    prime_to_indices[temp] = []
                prime_to_indices[temp].append(i)

        # Connect indices that share a prime factor
        for indices in prime_to_indices.values():
            for j in range(1, len(indices)):
                union(indices[0], indices[j])

        # Check if all indices are connected
        root = find(0)
        for i in range(1, n):
            if find(i) != root:
                return False

        return True
