To solve this problem, we need to find the shortest substring in a given string `s` that matches a pattern `p` containing exactly two '*' characters. The '*' character in the pattern can match any sequence of zero or more characters. The solution involves breaking down the pattern into three segments and efficiently searching for these segments in the string using the Knuth-Morris-Pratt (KMP) algorithm.

### Approach
1. **Split the Pattern**: The pattern `p` is split into three segments: `A`, `B`, and `C` based on the positions of the two '*' characters. This allows us to break down the problem into finding these segments in the string `s`.
2. **KMP Algorithm**: Use the KMP algorithm to find all occurrences of each segment (A, B, C) in the string `s`. This ensures efficient pattern matching in linear time.
3. **Handle Edge Cases**: Special handling for cases where any of the segments `A`, `B`, or `C` are empty strings.
4. **Search for Valid Substrings**: For each valid occurrence of segment `A`, search for valid subsequent occurrences of segment `B` and then segment `C` to determine the shortest valid substring.

### Solution Code
```python
class Solution:
    def shortestMatchingSubstring(self, s: str, p: str) -> int:
        star_positions = [i for i, c in enumerate(p) if c == '*']
        if len(star_positions) != 2:
            return -1
        star1, star2 = star_positions
        A = p[:star1]
        B = p[star1+1:star2]
        C = p[star2+1:]
        lenA, lenB, lenC = len(A), len(B), len(C)

        if lenA == 0 and lenB == 0 and lenC == 0:
            return 0

        A_positions = self.kmp(s, A)
        B_positions = self.kmp(s, B)
        C_positions = self.kmp(s, C)

        min_len = float('inf')
        import bisect

        if lenA == 0:
            if lenC == 0:
                if B:
                    return lenB
                else:
                    return 0 if C else -1
            else:
                if not B_positions or not C_positions:
                    return -1
                C_indices = sorted(C_positions)
                for b_start in B_positions:
                    b_end = b_start + lenB
                    idx = bisect.bisect_left(C_indices, b_end)
                    if idx < len(C_indices):
                        c_start = C_indices[idx]
                        current_len = (c_start + lenC) - b_start
                        if current_len < min_len:
                            min_len = current_len
                return min_len if min_len != float('inf') else -1

        elif lenC == 0:
            if not A_positions or not B_positions:
                return -1
            B_indices = sorted(B_positions)
            for a_start in A_positions:
                a_end = a_start + lenA
                idx = bisect.bisect_left(B_indices, a_end)
                if idx < len(B_indices):
                    b_start = B_indices[idx]
                    current_len = (b_start + lenB) - a_start
                    if current_len < min_len:
                        min_len = current_len
            return min_len if min_len != float('inf') else -1

        elif lenB == 0:
            if not A_positions or not C_positions:
                return -1
            C_indices = sorted(C_positions)
            for a_start in A_positions:
                a_end = a_start + lenA
                idx = bisect.bisect_left(C_indices, a_end)
                if idx < len(C_indices):
                    c_start = C_indices[idx]
                    current_len = (c_start + lenC) - a_start
                    if current_len < min_len:
                        min_len = current_len
            return min_len if min_len != float('inf') else -1

        else:
            if not A_positions or not B_positions or not C_positions:
                return -1
            B_indices = sorted(B_positions)
            C_indices = sorted(C_positions)
            for a_start in A_positions:
                a_end = a_start + lenA
                idxB = bisect.bisect_left(B_indices, a_end)
                if idxB >= len(B_indices):
                    continue
                b_start = B_indices[idxB]
                b_end = b_start + lenB
                idxC = bisect.bisect_left(C_indices, b_end)
                if idxC >= len(C_indices):
                    continue
                c_start = C_indices[idxC]
                current_len = (c_start + lenC) - a_start
                if current_len < min_len:
                    min_len = current_len
            return min_len if min_len != float('inf') else -1

    def kmp(self, s: str, pattern: str):
        if not pattern:
            return []
        occ = []
        m = len(pattern)
        n = len(s)
        lps = [0] * m
        length = 0
        i = 1
        while i < m:
            if pattern[i] == pattern[length]:
                length += 1
                lps[i] = length
                i += 1
            else:
                if length != 0:
                    length = lps[length-1]
                else:
                    lps[i] = 0
                    i += 1
        j = 0
        i = 0
        while i < n:
            if s[i] == pattern[j]:
                i += 1
                j += 1
                if j == m:
                    occ.append(i - m)
                    j = lps[j-1]
            else:
                if j != 0:
                    j = lps[j-1]
                else:
                    i += 1
        return occ
