class Solution:
    def minValidStrings(self, words: List[str], target: str) -> int:
        class TrieNode:
            def __init__(self):
                self.children = {}

        # Build Trie
        root = TrieNode()
        for word in words:
            node = root
            for char in word:
                if char not in node.children:
                    node.children[char] = TrieNode()
                node = node.children[char]

        n = len(target)
        dp = [float('inf')] * (n + 1)
        dp[0] = 0

