        # Subtract permutations with leading zero
        if counts[0] == 0:
            return total_perms
        # Compute permutations starting with zero
        new_counts = list(counts)
        new_counts[0] -= 1
        if new_counts[0] < 0:
            return total_perms
        product_leading = 1
        for c in new_counts:
            product_leading *= math.factorial(c)
        leading_perms = math.factorial(n - 1) // product_leading
        return total_perms - leading_perms
