                # Fully contained, skip (will be replaced)
                pass
            elif l < left and r > right:
                # Split into parts
                if l < left:
                    new_intervals.append((l, left - 1, v))
                if r > right:
                    new_intervals.append((right + 1, r, v))
            elif l < left:
                # Partial overlap on left
                new_intervals.append((l, left - 1, v))
            else:
                # Partial overlap on right
                new_intervals.append((right + 1, r, v))

        # Add new interval
        new_intervals.append((left, right, value))

        # Sort and merge adjacent intervals with same value
        new_intervals.sort()
        merged = []
        for l, r, v in new_intervals:
            if merged and merged[-1][1] + 1 == l and merged[-1][2] == v:
                merged[-1] = (merged[-1][0], r, v)
            else:
                merged.append((l, r, v))

        return merged

    def dp(op_idx, intervals):
        if op_idx == Q:
            return 1

        key = (op_idx, state_to_key(intervals))
        if key in memo:
            return memo[key]

        p, v = operations[op_idx]
        result = 0

        # Option 1: Set positions 1 to p to value v
        new_intervals = apply_operation(intervals, 1, p, v)
        if new_intervals is not None:
            result = (result + dp(op_idx + 1, new_intervals)) % MOD

        # Option 2: Set positions p to N to value v
        new_intervals = apply_operation(intervals, p, N, v)
        if new_intervals is not None:
            result = (result + dp(op_idx + 1, new_intervals)) % MOD

        memo[key] = result
        return result

    # Initially all positions have value 0
    initial_intervals = [(1, N, 0)]
    print(dp(0, initial_intervals))

solve()
