class Solution:
    def maximumSum(self, nums: List[int]) -> int:
        # Get the parity signature of a number (which primes appear odd number of times)
        def get_parity_signature(num):
            signature = {}
            i = 2
            while i * i <= num:
                count = 0
                while num % i == 0:
                    count += 1
                    num //= i
                if count % 2 == 1:  # Only record odd powers
                    signature[i] = 1
                i += 1
            if num > 1:  # If there's a remaining prime factor
                signature[num] = 1
            return tuple(sorted(signature.items()))  # Convert to tuple for hashability

        # Group numbers by their parity signature
        signature_sum = {}
        for num in nums:
            signature = get_parity_signature(num)
            if signature not in signature_sum:
                signature_sum[signature] = 0
            signature_sum[signature] += num

        # Return the maximum sum
        return max(signature_sum.values())
