class Solution:
    def countMentions(self, numberOfUsers: int, events: List[List[str]]) -> List[int]:
        # Initialize the number of mentions for each user
        mentions = [0] * numberOfUsers

        # Initialize the offline status for each user
        # For each user, store the timestamp until which they are offline
        offline_until = [0] * numberOfUsers

        # Sort events by timestamp
        events.sort(key=lambda event: int(event[1]))

        for event_type, timestamp, event_data in events:
            timestamp = int(timestamp)

            # Update the offline status of users
            for i in range(numberOfUsers):
                if offline_until[i] <= timestamp:
                    offline_until[i] = 0

            if event_type == "OFFLINE":
                user_id = int(event_data)
                offline_until[user_id] = timestamp + 60

            elif event_type == "MESSAGE":
                if event_data == "ALL":
                    # Mention all users
                    for i in range(numberOfUsers):
                        mentions[i] += 1
                elif event_data == "HERE":
                    # Mention all online users
                    for i in range(numberOfUsers):
                        if offline_until[i] <= timestamp:
                            mentions[i] += 1
                else:
                    # Mention specific users
                    user_ids = event_data.split()
                    for user_id in user_ids:
                        if user_id.startswith("id"):
                            user_id = int(user_id[2:])
                            if 0 <= user_id < numberOfUsers:
                                mentions[user_id] += 1

        return mentions
