class Solution:
    def minimumCost(self, target: str, words: List[str], costs: List[int]) -> int:
        n = len(target)
        dp = [float('inf')] * (n + 1)
        dp[0] = 0

        # Create a dictionary mapping each word to its minimum cost
        word_to_cost = {}
        for i, word in enumerate(words):
            if word not in word_to_cost or costs[i] < word_to_cost[word]:
                word_to_cost[word] = costs[i]

        # Create a set of all the unique lengths of the words
        lengths = set(len(word) for word in word_to_cost.keys())

        for i in range(1, n + 1):
            for length in lengths:
                if i >= length:
                    substr = target[i - length:i]
                    if substr in word_to_cost:
                        dp[i] = min(dp[i], dp[i - length] + word_to_cost[substr])

        return dp[n] if dp[n] != float('inf') else -1
