class Solution:
    def minimumCost(self, target: str, words: List[str], costs: List[int]) -> int:
        n = len(target)
        dp = [float('inf')] * (n + 1)
        dp[0] = 0

        # Preprocess the words and their costs
        word_to_cost = {}
        for i in range(len(words)):
            word = words[i]
            cost = costs[i]
            if word in word_to_cost:
                word_to_cost[word] = min(word_to_cost[word], cost)
            else:
                word_to_cost[word] = cost

        for i in range(1, n + 1):
            for word, cost in word_to_cost.items():
                if i >= len(word) and target[i-len(word):i] == word:
                    dp[i] = min(dp[i], dp[i-len(word)] + cost)

        return dp[n] if dp[n] != float('inf') else -1
